INSERT INTO `words` (`id`, `word_name`, `meaning_hindi`, `meaning_english`, `example`, `created_at`, `updated_at`) VALUES
(7, 'Set phasers to dumb.', '_', 'It’s a humorous insult used when someone thinks the situation or another person is acting stupid.', 'Get ready for something extremely stupid.”\r\n\r\n“Prepare yourself for dumb behavior.”\r\n\r\n“What’s coming next is going to be silly or foolish.', '2025-11-29 21:11:02', '2025-11-29 21:11:02'),
(8, 'devastated', 'अतिस्तब्ध और परेशान', 'extremely shocked and upset', 'They were devastated when their baby died', '2025-11-29 21:15:47', '2025-11-29 21:15:47'),
(9, 'Strap on a pair', '“Strap on a pair” is an informal, slightly rude/slang expression.', 'It means “be brave,” “man up,” or “gather courage and face something.”', '“Strap on a pair and tell them the truth.”\r\n→ Be brave and tell them honestly.', '2025-11-29 21:22:05', '2025-11-29 21:22:05'),
(10, 'Tentatively', '_', 'Tentatively means uncertainly, carefully, or not fully decided yet.', '“She smiled tentatively.”\r\n→ She smiled in a shy or uncertain way.\r\n\r\n“The meeting is tentatively scheduled for Monday.”\r\n→ The meeting is planned for Monday, but it’s not confirmed yet.', '2025-11-29 21:24:37', '2025-11-29 21:24:37'),
(11, 'Memoirs', 'Memoirs (pronounced: MEM-warz) means:', 'A memoir is a book or piece of writing in which a person writes about their own life experiences, memories, and events they lived through.', '“She wrote her memoirs about growing up in a small town.”\r\n\r\n“His memoirs describe his experiences in the army.”', '2025-11-29 21:26:26', '2025-11-29 21:26:56'),
(12, 'Hankering', 'Hankering = तीव्र इच्छा / ललक', 'Hankering = a strong wish for something', 'Hankering means a strong desire or craving for something.\r\n\r\n“I’m hankering for chocolate.”\r\n→ I really want chocolate.\r\n\r\n“He had a hankering to travel.”\r\n→ He strongly wished to travel.', '2025-11-29 21:29:48', '2025-11-29 21:29:48'),
(13, 'Blackout', 'loss of consciousness (fainting)', '.', '“He had a blackout after hitting his head.”', '2025-11-29 21:32:46', '2025-11-29 21:32:46'),
(14, 'I think your high on paint fumes', 'मुझे लगता है आप पेंट के धुएं से नशे में हैं', '.', '', '2025-11-29 21:37:08', '2025-11-29 21:37:08'),
(15, 'Amy already has a legal harp', 'एमी के पास पहले से ही एक कानूनी वीणा है', '.', '', '2025-11-29 21:38:50', '2025-11-29 21:38:50'),
(16, 'Factoids (pronounced: FAK-toydz) means:', '.', 'Small, interesting pieces of information — often fun facts, trivia, or brief facts.', 'Some factoids on social media are actually false', '2025-11-29 21:44:09', '2025-11-29 21:44:09'),
(17, 'Confide (pronounced: kun-FIDE) means:', 'Confide = भरोसा करके राज़ बताना', 'To trust someone with a secret or private information.', 'Confide = to tell someone something secretly because you trust them\r\n“She confided in me about her problems.”\r\n→ She trusted me and told me her private issues.\r\n\r\n“He only confides in his best friend.”\r\n→ He shares secrets only with him.', '2025-11-30 08:35:24', '2025-11-30 08:35:24'),
(18, 'Derided (pronounced: duh-RY-did)', 'Derided = मज़ाक उड़ाया / उपहास किया', 'To mock, make fun of, or ridicule someone in a mean or disrespectful way.', 'Derided = insulted / mocked / made fun of\r\n“His ideas were derided by the critics.”\r\n→ The critics made fun of his ideas.\r\n\r\n“She felt bad when her classmates derided her.”\r\n→ They mocked her.', '2025-11-30 08:38:10', '2025-11-30 08:38:10'),
(19, 'Goosebumps (pronounced: goos-bumps)', 'Goosebumps = रोमांच से खड़ा हुआ रोंगटा', 'Small bumps that appear on your skin when you feel:\r\n\r\nCold\r\n\r\nFear\r\n\r\nStrong emotion (excitement, shock, inspiration)', 'The horror movie gave me goosebumps.”\r\n\r\n“Her singing was so beautiful, I got goosebumps.”', '2025-11-30 08:44:47', '2025-11-30 08:44:47'),
(20, 'A scrunchy', '.', 'A scrunchy (or scrunchie) is a soft elastic hair tie used to tie hair.', '', '2025-11-30 08:58:52', '2025-11-30 08:58:52'),
(21, 'I heard Emma stirring', 'Stirring = हलचल करना / करवट लेना / जागने लगना', 'Someone named Emma is starting to wake up or moving slightly after being asleep or resting', 'Stirring = moving a little / waking up', '2025-11-30 09:01:43', '2025-11-30 09:01:43'),
(22, 'Original or crappy', 'Original (the real, authentic, high-quality version)\r\nor\r\n\r\nCrappy (poor quality, cheap, badly made, fake, or disappointing)', 'Original = real, authentic, first version\r\n\r\nCrappy = very bad, low quality (slang)', '“Is this movie the original or the crappy remake?”\r\n\r\n“Is your phone original or some crappy duplicate?”', '2025-11-30 09:05:26', '2025-11-30 09:05:26'),
(23, 'I don&#039;t see suds', 'मुझे झाग नहीं दिख रहा', '.', '', '2025-12-01 17:26:50', '2025-12-01 17:26:50'),
(24, 'Delicates', 'Delicates का मतलब है ऐसे कपड़े जो बहुत नाज़ुक होते हैं और जिन्हें धोते समय बहुत ध्यान रखना पड़ता है।', 'Clothes or fabrics that are easily damaged and need gentle handling, especially during washing.', 'I wash my delicates on a gentle cycle.\r\nमैं अपने delicates को जेंटल साइकल पर धोता हूँ।\r\n\r\nSilk sarees are considered delicates.\r\nसिल्क की साड़ियाँ delicates मानी जाती हैं।\r\n\r\nDon’t put your delicates in the dryer.\r\nअपने delicates को ड्रायर में मत डालो।', '2025-12-01 17:35:07', '2025-12-01 17:35:07'),
(25, 'What a geek!', 'Geek = nerdy person / someone who knows a lot about something\r\nGeek = पढ़ाकू / ज़्यादा ही शौक़ीन-टाइप व्यक्ति (कम्प्यूटर, गेम्स, साइंस का कीड़ा)', 'It usually means someone is:\r\n\r\nVery obsessed or deeply interested in something (computers, games, comics, science, etc.)\r\n\r\nA bit socially awkward or nerdy\r\n\r\nBut it can be said insultingly or affectionately, depending on tone.', 'He knows every detail about Star Wars — what a geek!”\r\n\r\nIf said lovingly: “Aww, you brought your science book on vacation? You’re such a geek!”', '2025-12-01 17:42:16', '2025-12-01 17:42:16'),
(26, 'Nerd', 'Nerd = बहुत पढ़ाकू / किताबों में डूबा रहने वाला', 'Someone who is very smart, studies a lot, and may be socially awkward.\r\nHigh intelligence\r\n\r\nLoves studying\r\n\r\nNot great with social situations', 'She always tops the class — she’s a nerd.', '2025-12-01 17:44:07', '2025-12-01 17:44:07'),
(27, 'Dork', 'Someone who is awkward, silly, or behaves in a goofy/clumsy way.\r\nDork = अजीब / थोड़ा बेवकूफ-सा / गड़बड़ करने वाला', 'Socially awkward\r\n\r\nMakes silly mistakes\r\n\r\nNot necessarily smart or passionate', '“He wore mismatched shoes — what a dork.”', '2025-12-01 17:45:08', '2025-12-01 17:45:08'),
(28, 'Humping = जानवर की तरह गलत हरकत करना / धक्का-मार हरकत', 'A thrusting movement similar to sex.', 'Sometimes “hump” can mean carry something heavy.', '“We were humping boxes up the stairs.”\r\n→ Carrying heavy boxes.', '2025-12-01 17:48:07', '2025-12-01 17:48:07'),
(29, 'You are all chaotic and twirl', 'Chaotic and twirly = बहुत उलझे हुए, बिखरे हुए और घूमते-फिरते से (बेचैन / उत्साहित)', 'Chaotic\r\n\r\nYou seem messy, disorganized, confused, or all over the place — like your energy is scattered.\r\n\r\nYou seem spinning around, excited, jumpy, hyper, or nervous — like you can’t sit still.', 'You’re acting very messy, over-excited, and full of wild energy right now', '2025-12-01 18:48:48', '2025-12-01 18:48:48'),
(30, 'Not too shabby', 'Not too shabby = काफ़ी अच्छा / बुरा नहीं है / उम्मीद से बढ़कर', 'Pretty good, better than expected, or not bad at all.', 'Your presentation was not too shabby!”\r\n→ It was good.\r\n\r\n“You cooked this? Not too shabby!”\r\n→ Surprisingly good.', '2025-12-01 18:59:14', '2025-12-01 18:59:14'),
(31, 'Shabby', 'Shabby = टूटा-फूटा / गंदा-पुराना / बेकार-सा', 'Old, worn-out, in bad condition, or of low quality.\r\nIt can also mean not respectable or poorly done.', 'He lives in a shabby room.”\r\n→ Old and in bad condition.\r\n\r\n“That was a shabby excuse.”\r\n→ Weak or poor-quality excuse.\r\n\r\n“Her clothes looked shabby.”\r\n→ Old or worn-out clothes.', '2025-12-01 19:01:11', '2025-12-01 19:01:11'),
(32, 'Somebody missed the offramp', 'Somebody missed the offramp = किसी ने रास्ता/दिशा गलत ले ली (शाब्दिक या मज़ाक में)।', 'Someone is off track\r\n\r\nSomeone lost focus\r\n\r\nSomeone went the wrong direction in a conversation\r\n\r\nSomeone made a mistake', '', '2025-12-01 19:09:29', '2025-12-01 19:09:29'),
(33, 'Dingy', 'dark, dirty-looking, dull, shabby', 'Old and dingy, बस इतना ही — पुराना और गंदा/उदास-सा।', 'Anything that looks old, dirty, or not well maintained', '2025-12-01 19:24:56', '2025-12-01 19:24:56'),
(34, 'Tacky', 'Tacky = भड़कीला, सस्ता-सा, बेमुश्किल / बुरी पसंद वाला', 'cheap-looking, flashy in a bad way, not stylish, not classy', '“Is this outfit tacky?”\r\n→ Does it look cheap or embarrassing?\r\n\r\n“The decorations are kind of tacky.”\r\n→ They look overdone or low-quality.', '2025-12-01 19:27:28', '2025-12-01 19:27:28'),
(35, 'Shut up cut it out', 'चुप रहो, इसे बंद करो।', ',', '', '2025-12-01 19:38:13', '2025-12-01 19:38:13'),
(36, 'Somebody was Winking at you', 'कोई तुम्हें आँख मार रहा था', '.', '', '2025-12-01 19:41:57', '2025-12-01 19:41:57'),
(38, 'boohockey / baloney / bull hockey', 'Nonsense\r\n➡️ Nonsense\r\n➡️ Something that is not true\r\n➡️ Ridiculous talk', '(Informal, humorous, mild substitute for “bullshit”)', '', '2025-12-02 20:29:22', '2025-12-02 20:29:22'),
(39, 'I know how miserable you are', 'मैं जानता हूँ कि तुम कितने दुखी हो', ',', '', '2025-12-02 20:48:56', '2025-12-02 20:48:56'),
(40, 'He blew us off', 'He ignored us / He didn’t show up / He canceled on us without caring', 'उसने हमें इग्नोर कर दिया', '', '2025-12-02 20:53:30', '2025-12-02 20:53:30'),
(41, 'skepticism', 'संदेह, शंका, या किसी बात पर आसानी से विश्वास न करना।', 'Skepticism means doubt, questioning attitude, or not easily believing something without proof.', 'There is a lot of skepticism about the new policy\r\nनई नीति को लेकर लोगों में काफी संदेह है।', '2025-12-02 20:57:11', '2025-12-02 20:57:11'),
(42, 'You are not so secret admirer.', 'इसका मतलब है कि व्यक्ति गुप्त प्रशंसक तो कहलाता है, लेकिन असल में गुप्त नहीं है —\r\nसबको पता है कि वह किसी को पसंद करता/करती है।', 'It means the person is supposed to be a secret admirer, but they are not actually secret — their feelings are obvious, or everyone can tell they like someone.', '', '2025-12-02 21:00:11', '2025-12-02 21:00:11'),
(43, 'I got my very own stalker.', '“मेरे पास मेरा खुद का एक स्टॉकर है।”\r\nयानि कोई व्यक्ति मेरे पीछे लगा हुआ है, मुझे लगातार देख रहा है, या मेरे बारे में ज़्यादा दिलचस्पी ले रहा है।', 'I have someone who is following me, watching me, or obsessively paying attention to me — like a stalker', '', '2025-12-02 21:02:43', '2025-12-02 21:02:43'),
(44, 'Of course this is just conjecture', 'बेशक यह सिर्फ अनुमान है', ',', '', '2025-12-03 16:42:29', '2025-12-03 16:42:29'),
(45, 'Pregnant woman slays four', 'A pregnant woman killed four people.', ',', '', '2025-12-03 16:49:36', '2025-12-03 16:49:36'),
(46, 'What’s happening to your ascent?', 'What is happening to your progress / rise / improvement?', 'Ascent = the act of going up, rising, or improving', 'When This Sentence Is Used\r\n\r\nThis is usually said when:\r\n\r\nSomeone was doing very well before\r\n\r\nTheir success or growth suddenly slowed down\r\n\r\nTheir career, learning, or performance is not improving now', '2025-12-03 17:00:54', '2025-12-03 17:00:54'),
(47, 'Ascent | Accent', '.', '.', 'Ascent (progress / rise)\r\nAccent (way of speaking)', '2025-12-03 17:02:09', '2025-12-03 17:02:09'),
(48, 'PROTOTYPE', 'Prototype = kisi cheez ka pehla trial version', 'A prototype is the first sample or test version of something before the final product is made.', 'This phone is just a prototype, not the final model.\r\n→ Ye phone sirf test version hai, final product nahi.', '2025-12-03 17:15:50', '2025-12-03 17:15:50'),
(49, 'Slurp', 'Slurp = chus-chus ki awaaz ke saath peena / peena ya khana', 'To make a loud wet sound while drinking or eating\r\nEspecially with soup, noodles, tea, or juice', 'He slurps his soup loudly.\r\n→ Wo soup zor-zor se chus-chus karke peeta hai.', '2025-12-03 17:21:25', '2025-12-03 17:21:25'),
(50, 'Interspersed', 'Interspersed = बीच-बीच में मिलाया हुआ / इधर-उधर फैला हुआ', 'Interspersed means spread among or scattered between other things at intervals (mixed in, not grouped together)\r\nInterspersed = mixed in between', 'Gaane ke beech beech mein ads interspersed hote rehte hain.\r\n\r\nUski kahani mein jokes interspersed the.', '2025-12-04 20:09:08', '2025-12-04 20:09:08'),
(51, 'I swoop in', 'Swoop in = अचानक तेजी से आ जाना (किसी काम के लिए)', '“I swoop in” means I enter suddenly and quickly—often to take action, help, or take advantage of a situation.', 'It comes from the way birds (like eagles) fly down quickly to catch something.\r\nI swoop in and save the day.\r\n→ I arrive suddenly and fix the problem.\r\n\r\nHe swooped in at the last moment and took the deal.\r\n→ He came suddenly and grabbed the opportunity.\r\n\r\nWhen everyone was confused, she swooped in with the solution.', '2025-12-04 20:17:50', '2025-12-04 20:17:50'),
(52, 'i thought i got to make the jokes', 'मैंने सोचा कि मुझे चुटकुले बनाने चाहिए', '.', '', '2025-12-04 20:20:09', '2025-12-04 20:20:09'),
(53, 'Cooper (Profession / Job)', 'Cooper woh aadmi hota hai jo lakdi ke barrel, drum ya peepas banata hai.', 'A cooper is a person who makes or repairs wooden barrels, tubs, and casks (for wine, water, oil, etc.).', 'The cooper made a wooden barrel for wine.\r\n\r\nBarrels are still made by skilled coopers.', '2025-12-05 21:22:42', '2025-12-05 21:22:42'),
(54, 'Cooper (Surname / Name)', 'Cooper ek English naam bhi hota hai (surname ya kabhi-kabhi first name).', 'Cooper is also a very common English family name (surname) and sometimes a first name.', 'My teacher’s last name is Cooper.\r\n\r\nBradley Cooper is a famous actor.', '2025-12-05 21:23:30', '2025-12-05 21:23:30'),
(55, 'Deviated', 'to change or become different from what is normal or expected', 'सामान्य या प्रत्याशित व्यवहार को बदलना या उससे हट कर आचरण करना लीक से हटना या हटाना उपयुक्त व्यवहार से हटना', '', '2025-12-05 21:26:18', '2025-12-05 21:26:18'),
(56, 'Contest', 'Contest = to challenge, disagree with, or oppose something (especially formally).', 'Contest ka matlab hota hai kisi baat ko challenge karna, usse disagree karna ya uske khilaaf ladna.', 'He contested the election results.\r\n→ He challenged the results.\r\n\r\nShe contested the case in court.\r\n→ She fought against the case legally.', '2025-12-05 21:31:46', '2025-12-05 21:31:46'),
(57, 'Wrestling with', 'Wrestling with = kisi baat se joojhna / struggle karna', 'Not physical fighting — it means:\r\n\r\nStruggling with\r\n\r\nMentally fighting with a problem', 'I’m wrestling with a tough decision.', '2025-12-05 21:39:19', '2025-12-05 21:39:19'),
(58, 'He is even more cunning than we thought', 'Cunning = chaalak, tez dimaag wala (thoda negative sense mein)', 'He is more clever and deceptive than we originally believed', '', '2025-12-05 21:54:15', '2025-12-05 21:54:15'),
(59, 'How likely is it that it will rain', 'बारिश होने की कितनी संभावना है?', '.', '', '2025-12-06 21:56:35', '2025-12-06 21:56:35'),
(60, 'What are the odds?', '.', 'This is the most common meaning. You say it when you’re asking how probable something is.', 'What are the odds that it will rain today?\r\n👉 How likely is it that it will rain?', '2025-12-06 21:58:14', '2025-12-06 21:58:14'),
(61, 'i got the stage fright', ',', 'Stage fright = fear or nervousness when speaking, performing, or being on stage in front of an audience.', '', '2025-12-06 22:15:35', '2025-12-06 22:15:35'),
(62, 'stink', 'To smell very bad.', '.', '', '2025-12-08 16:17:24', '2025-12-08 16:17:24'),
(63, 'Why don’t you use your thesaurus', 'तुम अपने शब्दकोश (Thesaurus) का इस्तेमाल क्यों नहीं करते?”\r\n(मतलब: एक ही शब्द बार-बार क्यों बोल रहे हो, अच्छे शब्द इस्तेमाल करो)', 'Why aren’t you using a thesaurus (a book/tool that gives synonyms', '', '2025-12-08 16:20:38', '2025-12-08 16:20:38'),
(64, 'Intense', 'Intense = Strong feeling or situation', 'Very strong, extreme, or powerful', '', '2025-12-08 16:39:19', '2025-12-08 16:39:19'),
(65, 'Insane', 'Mentally crazy; also used for something unbelievably wild', 'पागल / मानसिक रूप से असंतुलित', '', '2025-12-08 16:45:16', '2025-12-08 16:45:16'),
(66, 'Acrimonious', 'कड़वा, तीखा, कटु (बातचीत या बहस के लहजे में)', 'Acrimonious describes a bitter, angry, or harsh tone, especially during an argument or discussion.', 'Bitter fights\r\n\r\nHarsh words\r\n\r\nAngry disagreements', '2025-12-08 19:08:43', '2025-12-08 19:08:43'),
(67, 'It’s just steep', 'Price is too high (बहुत महंगा है)', 'Literal Meaning: Something is sharply inclined (ढलान वाला)\r\n\r\nUsed for hills, roads, stairs, slopes.', 'The price is just steep.\r\nकीमत बस थोड़ी ज्यादा है।\r\nDon’t worry, it’s just steep.\r\nचिंता मत करो, बस ढलान ज़्यादा है।', '2025-12-08 19:34:33', '2025-12-08 19:34:33'),
(68, 'Well, we could get that Everest video though.', '.', '.', '“We can still get that Everest video.”\r\n(Everest video = a video about Mount Everest, or a specific Everest-themed video.)\r\n\r\n“Though” adds the feeling of:\r\n\r\nat least we can do this\r\n\r\nthis is still an option\r\n\r\neven if something else didn’t work', '2025-12-08 19:37:05', '2025-12-08 19:37:05'),
(69, 'Why “though” is added at the end of a sentence', 'Because it:\r\n\r\nSoftens the statement\r\n\r\nAdds a contrast without sounding rude\r\n\r\nMakes speech sound natural and conversational\r\n\r\nWorks like “but” but lighter and softer', 'Sentence + though = but still / however / even then', 'When though comes at the end, it means:\r\n\r\n👉 A soft contrast\r\n👉 A correction or alternative\r\n👉 ‘At least / however / still’ kind of feeling\r\n\r\nIt makes the sentence sound more casual and friendly.', '2025-12-08 19:39:06', '2025-12-08 19:39:06'),
(70, '..', '..', '🎯 Easy Difference (One Line Each)\r\n\r\nThough = but still (casual)\r\n\r\nAlthough = though (formal)\r\n\r\nEven though = despite the fact (strong contrast)\r\n\r\nBut = simple “लेकिन”', '🧠 Super Easy Trick to Remember\r\n\r\nWant casual? → though\r\n\r\nWant formal? → although\r\n\r\nWant extra strong meaning? → even though\r\n\r\nWant simple contrast? → but', '2025-12-08 19:41:51', '2025-12-08 19:41:51'),
(71, 'Ditch -(Verb) – To abandon / leave / get rid of', 'छोड़ देना / अचानक गायब हो जाना / पलटा मार देना / पीछा छुड़ा लेना', 'To leave someone/something suddenly or irresponsibly; to skip; to get rid of.', 'He ditched me at the party.\r\nउसने मुझे पार्टी में छोड़ दिया और गायब हो गया।\r\n\r\nLet’s ditch the meeting.\r\nचलो मीटिंग छोड़ देते हैं।\r\n\r\nShe ditched her old phone.\r\nउसने अपना पुराना फोन छोड़ दिया।', '2025-12-08 19:48:59', '2025-12-08 19:48:59'),
(72, 'Ditch (Noun) – A trench', 'खाई / नाली', 'A long narrow hole beside roads or fields for water.', 'The car fell into a ditch.\r\nगाड़ी खाई में गिर गई।', '2025-12-08 19:49:51', '2025-12-08 19:49:51'),
(73, 'Did I startle you?', 'क्या मैं तुम्हें अचानक डराया / चौंकाया?', 'Did I surprise or scare you suddenly', 'If someone jumps or speaks suddenly and the other person reacts—\r\nYou ask: “Did I startle you?”', '2025-12-08 19:57:58', '2025-12-08 19:57:58'),
(74, 'Did I spook you? (very casual)', 'क्या मैंने तुम्हें डरा दिया?', '.', '', '2025-12-08 19:58:40', '2025-12-08 19:58:40'),
(75, 'Well I am in the house of Intruder', 'खैर मैं घुसपैठिये के घर में हूँ', '.', '', '2025-12-08 20:02:54', '2025-12-08 20:02:54'),
(76, 'You are dodging the question', 'तुम सवाल से बचना रहे हो / तुम सवाल टाल रहे हो।', 'You are avoiding answering the question, usually on purpose.', 'dodge = चकमा देना', '2025-12-08 20:06:36', '2025-12-08 20:06:36'),
(77, 'Demise', 'समाप्ति / खत्म हो जाना', 'The end or failure of something.', 'The company’s sudden demise shocked everyone.\r\nकंपनी की अचानक समाप्ति ने सबको चौंका दिया।', '2025-12-08 20:24:59', '2025-12-08 20:24:59'),
(78, 'Wow, someone’s flossing', '.', 'Flossing means showing off — especially showing off your money, looks, confidence, new things, or style.', '', '2025-12-09 19:34:20', '2025-12-09 19:34:20'),
(79, 'It was instinct', 'ये तो बस मेरी फितरत/सहज प्रतिक्रिया थी। मैंने सोचे बिना किया।”', 'When something is done by instinct, it means your body or mind reacted immediately and naturally, not because you planned it.', '', '2025-12-09 19:54:23', '2025-12-09 19:54:23'),
(80, 'Dripping . Slang Meaning (very common today)', 'बहुत स्टाइलिश, फ़ैन्सी, शो-ऑफ वाला स्टाइल.', '➡️ Someone or something looks extremely stylish, fashionable, or flashy.\r\n➡️ Showing off cool clothes, jewelry, or style.', 'He’s dripping today.”\r\n→ He is looking very stylish / fashionable.\r\n\r\n“Those shoes are dripping.”\r\n→ Very cool, stylish shoes.', '2025-12-09 20:01:41', '2025-12-09 20:01:41'),
(81, 'You look stunning”', '.', '➡️ You look extremely beautiful / handsome / amazing.\r\n➡️ You look so good that it surprises me.', '', '2025-12-09 20:19:17', '2025-12-09 20:19:17'),
(82, 'Elevation', 'Elevation = ऊँचाई / उन्नति', 'Elevation means height — how high something is above a particular level, usually sea level.', 'It tells you how high a place or object is.', '2025-12-10 20:44:45', '2025-12-10 20:44:45'),
(83, 'TRANSFORMATION', '(पूरी तरह बदल जाना / रूप या स्वरूप में बड़ा परिवर्तन)', 'A big change in form, structure, appearance, or nature.', 'The thing becomes something different than before.', '2025-12-10 20:46:05', '2025-12-10 20:46:05'),
(84, 'TRANSITION', 'एक स्थिति से दूसरी स्थिति में जाने की प्रक्रिया / परिवर्तन का चरण', 'A process of moving from one state, place, or stage to another.', 'It focuses on the journey or phase, not the final result.', '2025-12-10 20:47:55', '2025-12-10 20:47:55'),
(85, 'Diversity', 'विविधता / अलग-अलग प्रकारों का होना', 'Diversity means a mix of different kinds of people or things in the same group.\r\nDiversity = Difference + Variety + Mix', '', '2025-12-12 19:52:43', '2025-12-12 19:52:43'),
(86, 'I’m not going to ask why you are pimping on me for cheese.', '“मैं नहीं पूछने वाला कि तुम मुझसे पैसे के लिए क्यों दबाव डाल रहे हो/चिपक रहे हो।”', 'But in slang, “pimping” can loosely mean:\r\n\r\nmessing with someone\r\n\r\nbothering someone\r\n\r\nputting pressure on someone\r\n\r\ntrying to use them for something', '', '2025-12-12 19:56:48', '2025-12-12 19:56:48'),
(87, 'Mutation', '.', 'Mutation means a change in genes or DNA.', '', '2025-12-12 20:03:35', '2025-12-12 20:03:35'),
(88, 'Convention', 'परंपरा / रिवाज़ / आम तरीक़ा / नियम', 'A convention is a normal, accepted way of doing things in society, culture, or a group.', 'Shaking hands when you meet someone is a social convention.\r\n\r\nWearing formal clothes at a wedding is a cultural convention.\r\n\r\nTraffic rules are also conventions we all agree to follow.', '2025-12-12 20:14:45', '2025-12-12 20:14:45'),
(89, 'Inertia', 'An object resists change in its motion.\r\nInertia = चीज़ों का अपनी हालत न बदलने की जिद।', '✅ Inertia means:\r\n\r\nIf something is not moving, it wants to stay still.\r\n\r\nIf something is moving, it wants to keep moving in the same direction and speed.\r\n\r\nIt does not want to change unless an external force acts on it.', 'Inertia = tendency to resist change in motion.', '2025-12-12 20:19:16', '2025-12-12 20:19:16'),
(90, 'works like gangbusters', '.', '.', 'The new feature works like gangbusters.\r\n→ The feature works really well.\r\n\r\nOur marketing campaign is working like gangbusters.\r\n→ It’s getting excellent results.\r\n\r\nThis Docker setup works like gangbusters on Ubuntu.\r\n→ It runs smoothly and efficiently.', '2025-12-14 11:06:17', '2025-12-14 11:06:17'),
(91, 'Plunge', 'अचानक गिरना / तेज़ी से गिरना\r\n\r\nकूद जाना\r\n\r\nबिना सोचे-समझे किसी काम में लग जाना', 'To fall or drop suddenly and deeply\r\n\r\nTo jump or push into something quickly\r\n\r\nTo enter into a difficult or risky situation suddenly', 'The temperature plunged overnight.\r\n→ It dropped very fast.\r\n\r\nHe plunged into the river.\r\n→ He jumped into it.\r\n\r\nShe plunged into her new job.\r\n→ She started it suddenly and seriously.\r\n\r\nThe company’s profits plunged.\r\n→ Profits fell sharply.', '2025-12-14 11:35:29', '2025-12-14 11:35:29'),
(92, 'Replicate', 'To copy or duplicate exactly\r\n\r\nTo repeat an experiment or result to confirm it', 'Replicate means to make an exact copy of something or to repeat the same result or process.', 'The company replicated the design in all its new products.\r\n\r\nScientists tried to replicate the experiment to verify the results.\r\n\r\nThe artist couldn’t replicate the original painting perfectly.', '2025-12-14 19:00:13', '2025-12-14 19:00:13'),
(93, 'Scrimmage', 'Scrimmage = अभ्यास मैच / अभ्यास खेल\r\nScrimmage = a small, confused fight or struggle, not a full-scale battle.', 'practice game or training match where teams play seriously but the result doesn’t count officially.\r\nScrimmage = अभ्यास मैच / अभ्यास खेल', '', '2025-12-14 19:04:10', '2025-12-14 19:04:10'),
(94, 'Bazinga', 'Bazinga = मज़ाक था / बेवकूफ बनाया / फँसा लिया', 'When to use it\r\n\r\nAfter teasing someone\r\n\r\nAfter making a fake or sarcastic statement\r\n\r\nLight-hearted jokes only (not serious situations)\r\n\r\nIf you want, I can also explain why Sheldon says “Bazinga” or similar words like “gotcha” or “just kidding.”', '“Bazinga!” is said after a joke or trick to reveal:\r\n\r\n“I was kidding”\r\n\r\n“Got you!”\r\n\r\n“That was a prank.”', '2025-12-14 19:18:22', '2025-12-14 19:18:22'),
(95, 'Gloat', '.', 'to feel happy in a proud or slightly cruel way about someone else’s failure.', '', '2025-12-14 19:28:50', '2025-12-14 19:28:50'),
(96, 'Propensity', 'Propensity = प्रवृत्ति / झुकाव / स्वभाव\r\nUsually used for habits, behavior, or tendencies', 'Propensity means a natural tendency or inclination to behave in a particular way.\r\n👉 Something you are likely to do again and again because it’s in your nature', 'He has a propensity for taking risks.\r\n(उसे जोखिम लेने की प्रवृत्ति है।)\r\n\r\nChildren show a propensity to learn new languages quickly.\r\n\r\nHis propensity for anger caused problems at work.', '2025-12-14 19:36:34', '2025-12-14 19:36:34'),
(97, 'Perplexity', '= उलझन / भ्रम / हैरानी', 'Perplexity = confusion, puzzlement, or a state of not understanding something.', 'Perplexed → confused\r\n\r\nPerplex → to confuse', '2025-12-14 19:38:08', '2025-12-14 19:38:08'),
(98, 'Concede', '👉 To agree that something is correct or valid after resistance.\r\nConcede ka matlab hota hai maan lena, aksar tab jab hum pehle mana kar rahe hote hain.', 'Concede means to admit or accept something as true, often reluctantly (even if you don’t want to).', 'Admit a fact\r\n\r\nI concede that you were right.\r\n\r\nHe conceded his mistake.\r\n\r\nAccept defeat\r\n\r\nThe team conceded defeat.\r\n\r\nShe conceded the match.\r\n\r\nAllow or give up something\r\n\r\nThe company conceded some benefits to the workers.', '2025-12-15 16:21:06', '2025-12-15 16:21:06'),
(99, 'Creepy', 'Creepy ka matlab hota hai ajeeb aur daraavna lagna, jisse thoda sa dar ya discomfort ho.', 'Creepy means something that makes you feel uncomfortable, scared, or uneasy, often in a subtle or unsettling way (not always openly dangerous).', 'eerie\r\n\r\nspooky\r\n\r\nunsettling\r\n\r\nscary (mild, psychological)', '2025-12-15 16:27:39', '2025-12-15 16:27:39'),
(100, 'Why are you being such a jerk', 'तुम इतने बदतमीज़ क्यों बन रहे हो?', '.', '', '2025-12-16 19:21:06', '2025-12-16 19:21:06'),
(101, 'I can&#039;t believe you shoved me', 'मुझे विश्वास नहीं हो रहा कि तुमने मुझे धक्का दिया', '.', '', '2025-12-16 19:23:23', '2025-12-16 19:23:23'),
(102, 'Plausibly', '.', '“Plausibly” = in a way that seems realistic or believable', '“You could plausibly run into Bernardatee there.”\r\n→ It wouldn’t be surprising if you met Bernardatee by chance.\r\n\r\n“If you go to that café, you could plausibly run into your old boss.”\r\n→ It’s quite possible you might bump into them.', '2025-12-16 19:31:43', '2025-12-16 19:31:43'),
(103, 'Run into', '.', '“Run into” = meet unexpectedly', '', '2025-12-16 19:32:19', '2025-12-16 19:32:19'),
(104, 'Tenant', '.', 'A person who rents or occupies a property.', 'The tenant pays rent every month.\r\n\r\nYou could plausibly run into another tenant in the hallway.', '2025-12-16 19:42:09', '2025-12-16 19:42:09'),
(105, 'Tenet', '.', 'A principle, belief, or doctrine.', 'Honesty is a core tenet of the company.\r\n\r\nThat idea violates a basic tenet of scienc', '2025-12-16 19:42:52', '2025-12-16 19:42:52'),
(106, 'Cast', 'Meaning: To throw or fling something.\r\n\r\nHe cast the net into the sea.\r\n\r\nShe cast a stone across the river.', 'Meaning: The group of actors in a film, TV show, or play.\r\n\r\nThe cast of the movie is amazing.\r\n\r\nShe’s part of the main cast.', 'Common phrases\r\n\r\nCast a glance → look briefly\r\n\r\nCast doubt → make something seem uncertain\r\n\r\nCast a spell → use magic (or metaphorically influence)', '2025-12-16 19:46:59', '2025-12-16 19:46:59'),
(107, 'retraction', 'Retraction = a formal or clear withdrawal of a statement, claim, or accusation.', '“Retraction” means taking something back after it was said, written, or claimed.', 'The newspaper issued a retraction of the false report.\r\n\r\nHe demanded a public retraction of the accusation.\r\n\r\n👉 Often used for mistakes, false claims, or defamation.', '2025-12-16 19:51:34', '2025-12-16 19:51:34'),
(108, 'Suck', '“Suck” in casual English = are bad, are awful, are annoying.', 'Very casual\r\n\r\nSlightly rude / blunt\r\n\r\nCommon in spoken English', 'This app sucks. → This app is bad.\r\n\r\nThat movie sucked. → That movie was terrible.\r\n\r\nMondays suck. → Mondays are unpleasant.', '2025-12-16 19:53:27', '2025-12-16 19:54:04'),
(109, 'Don&#039;t be Silly my voice is Deep and sorous', 'मूर्ख मत बनो, मेरी आवाज़ गहरी और कर्कश है।', '.', '', '2025-12-16 19:56:47', '2025-12-16 19:56:47'),
(110, 'Why would you be enraged', 'आपको गुस्सा क्यों आएगा?', '.', '', '2025-12-16 20:00:16', '2025-12-16 20:00:16'),
(111, 'Can you tell I am perspiring a little', 'क्या आपको पता चल रहा है कि मुझे थोड़ा पसीना आ रहा है?', '.', '', '2025-12-17 19:25:06', '2025-12-17 19:25:06'),
(112, 'I think I might have a little concussion', 'I think I might have a little concussion', '.', '', '2025-12-17 19:29:45', '2025-12-17 19:29:45'),
(113, 'We could just wing it', 'हम बिना तैयारी के भी काम चला सकते हैं।', '“To wing it”: to do something without preparation.\r\nExample: I didn’t study, so I just winged the exam.', '', '2025-12-17 19:35:55', '2025-12-17 19:36:59'),
(114, 'Restraint', 'Restraint means control, limitation, or the act of holding back.', 'Restraint = controlling your emotions, actions, or desires\r\n\r\nShe showed great restraint and didn’t argue.\r\n\r\nHe spoke with restraint despite being angry.', '', '2025-12-17 20:07:14', '2025-12-17 20:07:14'),
(115, 'When I feel stifled', 'जब मुझे घुटन महसूस होती है', '.', '', '2025-12-17 20:18:48', '2025-12-17 20:18:48'),
(116, 'Flaws', 'defect, fault, shortcoming, weakness', 'Weaknesses or defects in something\r\nImperfections in a person, object, plan, or system', 'Every human has flaws.\r\n\r\nThe plan has a major flaw.\r\n\r\nDespite its flaws, the app works well.', '2025-12-18 12:44:51', '2025-12-18 12:44:51'),
(117, 'Frowns', 'She frowns when she doesn’t understand something.\r\n\r\nThe teacher frowned at the noisy students.\r\n\r\nHis comment earned a few frowns from the audience.', 'A frown is a facial expression where the eyebrows are drawn together and the corners of the mouth turn down. It usually shows displeasure, anger, confusion, worry, or disapproval.', '', '2025-12-18 12:46:08', '2025-12-18 12:46:08'),
(118, 'Reins', 'Reins are the straps used to control a horse by attaching them to the bit in its mouth.\r\nFiguratively, reins means control or authority.', 'She pulled the reins to stop the horse.\r\nOften confused with:\r\n\r\nReigns → rules (a king reigns)\r\n\r\nRains → water falling from the sky 🌧️', 'Take the reins → assume control\r\n\r\nKeep a tight rein on → control strictly\r\n\r\nGive free rein → allow complete freedom', '2025-12-18 12:47:28', '2025-12-18 12:47:28'),
(119, 'Enunciated', 'She enunciated every word so the audience could understand.\r\n\r\nThe actor enunciated his lines perfectly.\r\n\r\nPlease enunciate when you speak.', 'Enunciated means spoken clearly and distinctly, with each sound or word properly pronounced.', 'Opposite:\r\nmumbled, slurred', '2025-12-18 12:49:27', '2025-12-18 12:49:27'),
(120, 'Surpass', 'Surpass means to be better than, greater than, or to go beyond someone or something.', 'Common patterns:\r\n\r\nsurpass expectations\r\n\r\nsurpass limits\r\n\r\nsurpass competitors', 'She surpassed everyone’s expectations.\r\n\r\nThis year’s sales surpassed last year’s.\r\n\r\nHis skills surpass mine.', '2025-12-18 12:52:36', '2025-12-18 12:52:36'),
(121, 'Revolts', 'Revolts are uprisings or rebellions against authority, government, or control.', 'To revolt means:\r\n\r\nTo rebel or rise up against authority\r\n\r\nThe soldiers revolted against their commander.\r\n\r\nTo feel strong disgust or shock\r\n\r\nThe violence revolts me.', '', '2025-12-18 12:55:04', '2025-12-18 12:55:04'),
(122, 'Conception', 'Conception means the beginning or creation of an idea, plan, or belief.\r\nThe project changed after its initial conception.\r\n\r\nHer conception of success is different from mine.', 'Related forms:\r\n\r\nConceive (verb) – to form an idea or become pregnant\r\n\r\nConcept (noun) – an idea', '', '2025-12-18 12:58:36', '2025-12-18 12:58:36'),
(123, 'Surge of energy', 'A surge of energy means a sudden, strong increase in energy, strength, or excitement.', 'After resting, she felt a surge of energy.\r\n\r\nThe music gave him a surge of energy.\r\n\r\nHearing the news sent a surge of energy through the crowd.', 'burst of energy\r\n\r\nrush of energy\r\n\r\nsudden boost', '2025-12-18 13:08:52', '2025-12-18 13:08:52'),
(124, 'Sustainability', 'Sustainability is the ability to maintain or continue something over the long term without causing harm to the environment, society, or resources. It’s often used in environmental, economic, and social contexts.', '.', 'Renewable energy sources promote sustainability.\r\n\r\nThe company focuses on sustainability in its production.\r\n\r\nSustainability is important for protecting the planet for future generations.', '2025-12-18 13:10:10', '2025-12-18 13:10:10'),
(125, 'after “endow”, you usually need “with” to specify what is being given.', 'Endow → to give or provide a quality, ability, or gift', 'I will endow you with the skills to pursue your dreams.\r\n\r\nThe scholarship will endow you to pursue higher education.', '“I will endow you to pursue [something].” → I will give you the means, ability, or resources to pursue [a goal or ambition].', '2025-12-18 13:15:15', '2025-12-18 13:15:15'),
(126, 'Annulment', 'Annulment means to officially declare something invalid or void, as if it never legally existed.', 'he judge annulled the previous ruling.', '', '2025-12-18 16:13:15', '2025-12-18 16:13:15'),
(127, 'impersonator', 'Impersonator means a person who pretends to be someone else, usually by copying their voice, appearance, or behavior.', 'Impersonator → नकल करने वाला व्यक्ति / किसी और का रूप धारण करने वाला', '', '2025-12-18 16:16:09', '2025-12-18 16:16:09'),
(128, 'slob', 'Slob means a very messy, dirty, or untidy person.\r\nIt’s an informal and slightly insulting word.', 'Someone who doesn’t care about cleanliness or order', 'Slob → गंदा व्यक्ति / बहुत लापरवाह इंसान', '2025-12-18 16:23:59', '2025-12-18 16:23:59'),
(129, 'Slumber', 'Slumber means sleep, especially a deep, calm, or peaceful sleep.', '.', '', '2025-12-18 19:08:05', '2025-12-18 19:08:05'),
(130, 'I have stipulated in the contract', 'मैंने अनुबंध में यह शर्त रखी है।', '.', '', '2025-12-18 19:23:08', '2025-12-18 19:23:08'),
(131, 'Addendum', 'something added later to a document, agreement, or discussion', '.', '', '2025-12-18 19:29:07', '2025-12-18 19:29:07'),
(132, 'tremble', 'to shake, for example because you are cold, frightened, etc.', '(ठंड, डर आदि के कारण) काँपना', 'She was pale and trembling with shock.', '2025-12-19 08:00:17', '2025-12-19 08:00:17'),
(133, 'Contempt = “I don’t respect you at all.”', 'Pathetic means so poor, weak, or disappointing that it causes pity or contempt.', '.', '', '2025-12-19 08:37:27', '2025-12-19 08:37:27'),
(134, 'Prudent', 'प्रूडेंट (Prudent) → समझदार, सावधान, विवेकपूर्ण', 'Prudent means careful, wise, and sensible, especially when making decisions about the future.', 'It’s prudent to save some money every month.\r\n\r\nShe made a prudent decision by checking the contract carefully.\r\n\r\nWearing a helmet is a prudent safety measure.', '2025-12-19 16:00:26', '2025-12-19 16:00:26'),
(135, 'extravagance', 'फिजूलखर्ची', '.', '', '2025-12-19 16:01:43', '2025-12-19 16:01:43'),
(136, 'I envy you', 'मुझे तुमसे ईर्ष्या है', '.', '', '2025-12-19 16:04:28', '2025-12-19 16:04:28'),
(137, 'Everyone is mine to torment', 'हर कोई मेरे वश में है, मैं उसे सता सकता हूँ।', '.', '', '2025-12-19 16:26:35', '2025-12-19 16:26:35'),
(138, 'Of course they will be hate you as a disaster', 'बेशक वे आपको एक आपदा मानकर नफरत करेंगे।', '.', '', '2025-12-19 16:59:05', '2025-12-19 16:59:05'),
(139, 'stature', 'Physical → कद, काठी\r\n\r\nFigurative → प्रतिष्ठा, हैसियत,', 'tature means height, importance, or reputation, depending on context.', '', '2025-12-19 18:46:33', '2025-12-19 18:46:33'),
(140, 'You still slouch', 'तुम अब भी झुके रहते हो', '.', '', '2025-12-19 19:05:39', '2025-12-19 19:05:39'),
(141, 'hush now', 'अब चुप्पी', '.', '', '2025-12-19 19:14:00', '2025-12-19 19:14:00'),
(142, 'He owes him nothing', 'वह उसका कुछ भी ऋणी नहीं है', '.', '', '2025-12-19 19:26:33', '2025-12-19 19:26:33'),
(143, 'It&#039;s not Mercy letting in a child linger in such pain', 'किसी बच्चे को इस तरह दर्द में तड़पने देना दया नहीं है।', '.', '', '2025-12-19 19:58:10', '2025-12-19 19:58:10'),
(144, 'What you see is dwarf', 'जो आप देख रहे हैं वह बौना है', '.', '', '2025-12-19 20:19:04', '2025-12-19 20:19:04'),
(145, 'my repulsive nephew will be the king after him', 'मेरा घिनौना भतीजा उसके बाद राजा बनेगा', '.', '', '2025-12-19 20:20:34', '2025-12-19 20:20:34'),
(146, 'Stern', 'Adjective → कठोर, सख़्त, गंभीर\r\n\r\nNoun (ship) → जहाज़ का पिछला हिस्सा', 'Serious, strict, and firm, not gentle or playful.', 'Example: “The teacher gave him a stern warning.”\r\n\r\nExample: “She spoke in a stern voice.”', '2025-12-19 20:59:43', '2025-12-19 20:59:43'),
(147, 'Slogging through the mud', 'कीचड़ में धक्के खाते हुए', '.', '', '2025-12-20 15:02:00', '2025-12-20 15:02:00'),
(148, 'Probably shattered every rib he had', 'शायद उसकी हर पसली टूट गई थी', 'Shattered means broken into many pieces or emotionally/physically exhausted or .', 'Broken physically\r\n\r\nThe glass was shattered.\r\n→ Broken into many small pieces.\r\n\r\nEmotionally devastated\r\n\r\nShe was shattered by the news.\r\n→ Deeply upset or heartbroken.\r\n\r\nExtremely tired (informal)\r\n\r\nI’m absolutely shattered.\r\n→ Very exhausted.', '2025-12-20 15:03:36', '2026-01-03 17:20:23'),
(149, 'Piss off', 'To go away / leave me alone\r\n→ Used angrily to tell someone to stop bothering you.\r\nExample:\r\n\r\nHe told the salesman to piss off.', 'To annoy or anger someone (less common, British usage)\r\nExample:\r\n\r\nThat comment really pissed me off.', '“Piss off” is an informal, rude phrase in English. It has two common meanings:', '2025-12-20 16:00:14', '2025-12-20 16:00:14'),
(150, 'Piss into', '“Piss into” means to urinate inside something (a container, place, or area).', 'Literal: to urinate into a place or object\r\nExample:\r\n\r\nHe pissed into the bottle because there was no restroom.', 'Vulgar / offensive\r\n\r\nUsed in casual, angry, or rough speech\r\n\r\nAvoid in formal or public situations', '2025-12-20 16:01:49', '2025-12-20 16:01:49'),
(151, 'their smug face', 'उनका आत्मसंतुष्ट चेहरा', '.', '', '2025-12-20 16:04:02', '2025-12-20 16:04:02'),
(152, 'sentry', 'पहरेदार', '.', '', '2025-12-20 16:05:31', '2025-12-20 16:05:31'),
(153, 'Spare me', 'मुझे बख्श दो', 'mujhe bakhsh do', '', '2025-12-20 16:36:49', '2025-12-20 16:36:49'),
(154, 'Ponderous', 'कष्टकारक भारी, सुस्त, बोझिल', 'Ponderous means slow, heavy, or serious in a way that feels boring or tiring.', '', '2025-12-20 16:58:55', '2025-12-20 16:58:55'),
(155, 'Demented mind', '.', 'a mind that is confused, unstable, or not thinking clearly (not necessarily medical dementia)', 'The dying mind is a demented mind', '2025-12-20 17:04:21', '2025-12-20 17:04:21'),
(156, 'I am here for the feast', 'मैं दावत के लिए यहाँ आया हूँ', '.', '', '2025-12-20 21:10:58', '2025-12-20 21:10:58'),
(157, 'Lord staff has been charged for this treason', 'लॉर्ड स्टाफ पर इस राजद्रोह का आरोप लगाया गया है।', '.', '', '2025-12-21 12:27:29', '2025-12-21 12:27:29'),
(158, 'Fester', 'The injury festered without treatment.\r\n\r\nResentment festered for years.', 'To become worse over time, especially because it’s ignored.\r\n\r\nWound: becomes infected\r\n\r\nFeeling/problem: grows bitter or angry', '', '2025-12-21 14:04:06', '2025-12-21 14:04:06'),
(159, 'Try to penetrate the Enigma that is me', 'मुझमें छिपी पहेली को सुलझाने का प्रयास करें।', '.', '', '2025-12-21 14:15:14', '2025-12-21 14:15:14'),
(160, 'when they castreted you did they take the pillar with the stones', 'जब उन्होंने तुम्हें नपुंसक बनाया, तो क्या वे पत्थरों सहित स्तंभ भी ले गए थे?', '.', '', '2025-12-21 15:18:15', '2025-12-21 15:18:15'),
(161, 'That’s whack', 'Tone\r\n\r\nInformal\r\n\r\nOften annoyed, judgmental, or unimpressed', 'It means something is bad, stupid, unfair, weird, or disappointing.', 'Similar slang\r\n\r\nThat sucks\r\n\r\nThat’s lame\r\n\r\nThat’s messed up\r\n\r\nThat’s trash (stronger)', '2025-12-21 21:10:37', '2025-12-21 21:10:37'),
(162, 'Vows', 'Vows are serious, formal promises, especially ones that are deeply meaningful.', 'A vow is stronger than a normal promise — it’s meant to be kept no matter what.', 'Examples of vows:\r\n\r\nTo love\r\n\r\nTo stay faithful\r\n\r\nTo support each other', '2025-12-21 21:14:51', '2025-12-21 21:14:51'),
(163, 'Crap', 'Nonsense / lies\r\n\r\nThat’s a load of crap.\r\n\r\nStop talking crap.', '1. Something bad or useless\r\n\r\nThis phone is crap.\r\n\r\nThat movie was total crap.', 'Trouble or mess\r\n\r\nI’m in deep crap now.', '2025-12-21 21:16:03', '2025-12-21 21:16:03'),
(164, 'They get spook by their own shadow', 'वे अपनी ही परछाई से डर जाते हैं', '.', '', '2025-12-22 15:45:02', '2025-12-22 15:45:02'),
(165, 'Outrage', 'The decision caused public outrage.\r\n\r\nThere was widespread outrage over the unfair verdict.', 'Outrage means a strong feeling of anger or shock, usually caused by something unjust, offensive, or morally wrong.', 'ynonyms\r\n\r\nFury\r\n\r\nIndignation\r\n\r\nAnger\r\n\r\nShock', '2025-12-22 15:53:20', '2025-12-22 15:53:20'),
(166, 'You will withdraw this filthy accusations', 'आप इन घिनौने आरोपों को वापस लेंगे।', '.', '', '2025-12-22 16:37:09', '2025-12-22 16:37:09'),
(167, 'Squired', 'In medieval times, to be squired meant:\r\n\r\nAssisting a knight\r\n\r\nCarrying armor or weapons\r\n\r\nTraining under them', 'The sentence “I squired for you once.” means:\r\n👉 “I once served you as a squire.”\r\n👉 “I used to be your attendant or helper.”', 'I squired for you → I acted as your assistant / apprentice, especially in a medieval or knightly sense', '2025-12-22 19:44:21', '2025-12-22 19:44:21'),
(168, 'Each more daunting the last', 'प्रत्येक अंतिम से अधिक चुनौतीपूर्ण था', '.', '', '2025-12-22 20:25:28', '2025-12-22 20:25:28'),
(169, 'So I ignore the please of damsel in distress', 'इसलिए मैं संकट में फंसी युवती की गुहार को नजरअंदाज कर देता हूँ।', '.', '', '2025-12-23 21:55:23', '2025-12-23 21:55:23'),
(170, 'The subtlties of politics are often lost on me', 'राजनीति की बारीकियां अक्सर मेरी समझ से परे होती हैं।', ',', '', '2025-12-24 19:45:53', '2025-12-24 19:45:53'),
(171, 'Sobriety', 'Sobriety means a state of being free from the influence of alcohol or drugs—in other words, being clear-headed, alert, and in control', '.', 'They have all suffered through my bouts of Sobriety\r\nउन सभी ने मेरी नशामुक्ति की अवधि को सहा है।', '2025-12-24 20:10:27', '2025-12-24 20:10:27'),
(172, 'It&#039;s very tedious for all concerned', 'इससे जुड़े सभी लोगों के लिए यह बहुत थकाऊ है।', '.', '', '2025-12-24 20:11:43', '2025-12-24 20:11:43'),
(173, 'Severity', 'Severity refers to the degree of seriousness, intensity, or harshness of something.', 'Severe (adjective): very serious or intense\r\n\r\nSeverely (adverb): in a serious or intense way', 'Severity of an illness → how serious the disease is\r\n\r\nSeverity of punishment → how harsh the punishment is\r\n\r\nSeverity of weather → how extreme or dangerous the weather is\r\n\r\nSeverity of pain → how intense the pain feels', '2025-12-25 10:08:44', '2025-12-25 10:08:44'),
(174, 'Seduce away', 'To lure or tempt someone away from their current loyalty, relationship, belief, or duty—usually through charm, attraction, or persuasion.', 'She was seduced away from her principles.\r\n\r\nHe tried to seduce her away from her family’s influence.\r\n\r\nIt implies intentional influence, sometimes manipulative or romantic.', '', '2025-12-25 11:29:23', '2025-12-25 11:29:23'),
(175, 'Sulking', 'Sulking = showing silent anger, disappointment, or resentment, often by withdrawing or refusing to engage.', '.Prickly: easily annoyed, touchy, not very approachable', '', '2025-12-25 21:28:56', '2025-12-25 21:30:59'),
(176, 'Fierce', 'Intensely strong, aggressive, or powerful\r\n“A fierce storm hit the coast.”', 'Bold, confident, and formidable (often positive)\r\n“She’s a fierce competitor.”\r\n“He’s fierce in debate.”', 'Passionate or intense in feeling\r\n“Fierce loyalty.”\r\n“Fierce determination.”', '2025-12-25 21:39:39', '2025-12-25 21:39:39'),
(177, 'Despise', 'Despise = strong dislike mixed with contempt', 'stronger than dislike, harsher than hate', '', '2025-12-25 21:46:03', '2025-12-25 21:46:03'),
(178, 'Sulk all you want', 'The speaker is saying they won’t change their behavior or feel guilty, even if the other person stays angry or moody.', 'Go ahead and be upset if you like—I don’t care.', 'Tone\r\n\r\nUsually cold, irritated, or defiant\r\n\r\nCan sound insulting or provocative\r\n\r\nImplies emotional indifference', '2025-12-26 16:55:02', '2025-12-26 16:55:02'),
(179, 'strangled', '.', 'To kill or seriously harm someone by cutting off their air supply, usually by squeezing the neck.\r\n\r\nMore generally, to choke or compress something so it cannot breathe or function.', '', '2025-12-26 17:19:01', '2025-12-26 17:19:01'),
(180, 'dispense with', '“dispense with” means to do without, to cancel, or to decide something is unnecessary.', 'Formal and cold\r\n\r\nSounds final, detached, and emotionally distant\r\n\r\nOften used in dramatic dialogue, especially to signal rejection or a broken engagement', '', '2025-12-26 17:35:03', '2025-12-26 17:35:03'),
(181, 'Devise', '.', 'To plan, invent, or create something carefully, often with thought or ingenuity.', 'She devised a clever solution to the problem.\r\n\r\nThe engineers devised a new system.\r\n\r\nThe gods couldn’t devise a more perfect tongue.\r\n→ create or design', '2025-12-26 17:44:00', '2025-12-26 17:44:00'),
(182, 'Spurned', 'To reject someone or something harshly, proudly, or with contempt\r\n\r\nTo refuse disdainfully, often implying insult or hurt feelings', 'She spurned his apology.\r\n\r\nHe felt spurned after his proposal was rejected.\r\n\r\nThe offer was spurned by the committee.', '', '2025-12-26 18:01:44', '2025-12-26 18:01:44'),
(183, 'How do you not make a first down there', 'वहाँ प्रथम स्थान कैसे नहीं हासिल किया जा सकता?', '.', '', '2025-12-27 19:07:17', '2025-12-27 19:07:17'),
(184, 'Pervert (noun)', 'Pervert (noun): an insult meaning a person who has abnormal, improper, or socially unacceptable sexual interests or behavior.', 'The sentence implies that the speaker has heard a rumor or accusation about someone’s character.', '“I hear you are a pervert.”\r\nmeans\r\n“People say you have inappropriate or abnormal sexual behavior.”', '2025-12-28 15:40:58', '2025-12-28 15:40:58'),
(185, 'Invaded', 'Invaded means entered a place or situation forcefully, without permission, or in an unwelcome way.', 'Invaded = came in where it was not wanted', 'To enter someone’s space, life, or privacy without permission\r\n👉 He felt his privacy was invaded.', '2025-12-28 17:33:49', '2025-12-28 17:33:49'),
(186, 'implores', 'Implores means begs earnestly or desperately, especially in a serious or emotional way.', 'It shows urgency, desperation, or strong emotion.', 'She implores him to stay.\r\n\r\nThe child implored for mercy.\r\n\r\nHe implores the judge for leniency.', '2025-12-28 17:42:06', '2025-12-28 17:42:06'),
(187, 'sorcery', 'the art or use of magic in which the power of evil, supernatural forces or black magic is used', '.', '', '2025-12-28 17:44:35', '2025-12-28 17:44:35'),
(188, 'They can never be tamed', 'इन्हें कभी वश में नहीं किया जा सकता।', '.', '', '2025-12-29 16:26:58', '2025-12-29 16:26:58'),
(189, 'I know that&#039;s tempting', 'मुझे पता है कि यह लुभावना है।', '.', '', '2025-12-30 15:44:07', '2025-12-30 15:44:07'),
(190, 'This is my wad', 'ये मेरा बंडल है', '.', '', '2025-12-30 19:03:54', '2025-12-30 19:03:54'),
(191, 'pimp', 'pimp is a person who controls or manages prostitutes, arranging clients for them and taking a share of their earnings.\r\n\r\nThis meaning is negative and illegal in most places.', 'To pimp something means to promote, show off, or make it look more attractive, often in a flashy way.', 'Slang / Pop culture\r\n\r\nSometimes used casually to mean stylish, flashy, or impressive, though this usage can still be offensive to some people.', '2025-12-30 19:08:27', '2025-12-30 19:08:27'),
(192, 'Regicide', 'Regicide means the act of killing a king or monarch.\r\n\r\nFrom Latin: rex (king) + -cide (killing)\r\n\r\nIt is con', 'My Trial for Regicide\r\nA legal trial in which I am accused of killing a king.', '', '2025-12-31 16:29:42', '2025-12-31 16:29:42');
INSERT INTO `words` (`id`, `word_name`, `meaning_hindi`, `meaning_english`, `example`, `created_at`, `updated_at`) VALUES
(193, 'Intolerant', 'Unable or unwilling to accept differences (opinions, beliefs, people), or', 'Unable to tolerate something physically or mentally', '', '2025-12-31 18:47:09', '2025-12-31 18:47:09'),
(194, 'Maybe it&#039;s a comet', 'शायद यह एक धूमकेतु है', ',', '', '2025-12-31 18:51:25', '2025-12-31 18:51:25'),
(195, 'I hogged all of the credit', 'मैंने सारा श्रेय खुद ले लिया।', '.', '', '2025-12-31 18:55:24', '2025-12-31 18:55:24'),
(196, 'perilous', 'Perilous means full of danger or likely to cause harm, loss, or failure.', 'imple meaning\r\n\r\nDangerous\r\n\r\nRisky\r\n\r\nUnsafe', 'Synonyms\r\n\r\nDangerous\r\n\r\nRisky\r\n\r\nHazardous\r\n\r\nTreacherous', '2026-01-01 10:24:50', '2026-01-01 10:24:50'),
(197, 'consolation', 'comfort after disappointment or loss', '.', '', '2026-01-01 10:35:28', '2026-01-01 10:35:28'),
(198, 'Consolidate', 'To combine, strengthen, or make something more solid or stable.', 'Examples:\r\n\r\nThe company decided to consolidate its departments.\r\n\r\nHe took time to consolidate his position at work.\r\n\r\nAfter learning the basics, you should consolidate your knowledge.\r\n\r\nRelated words: unite, merge, strengthen', '', '2026-01-01 10:45:08', '2026-01-01 10:45:08'),
(199, 'Lurking and simpering on the stairs like buzzards', 'Lurking → hiding or waiting secretly, usually with bad intent\r\n\r\nSimpering → smiling in a fake, silly, or flattering way\r\n\r\nBuzzards → birds of prey that circle and wait for something to die', 'The line describes people who are:\r\n\r\nHanging around secretly\r\n\r\nPutting on fake, ingratiating smiles\r\n\r\nWaiting to benefit from someone’s weakness or downfall', '', '2026-01-01 11:02:11', '2026-01-01 11:02:11'),
(200, 'Trying to get their claws in me', 'मुझ पर अपना शिकंजा कसने की कोशिश कर रहे हैं', 'claws ;पंजे', '', '2026-01-01 11:04:04', '2026-01-01 11:04:04'),
(201, 'Decent', 'Uses:\r\n\r\nDescribes people, behavior, or things', 'Morally good, respectable, or acceptable in behavior or quality.', 'Decency\r\n\r\nMeaning:\r\nThe quality or standard of being decent; proper moral behavior or respect.', '2026-01-01 11:26:18', '2026-01-01 11:26:18'),
(202, 'Mourn', 'Mourn means to feel or show deep sadness, especially because someone has died or something important has been lost.', 'Simple meaning\r\n\r\nTo grieve\r\n\r\nTo feel sorrow for a loss', '', '2026-01-01 11:28:28', '2026-01-01 11:28:28'),
(203, 'I am a dork', 'मैं एक बेवकूफ हूँ', '.', '', '2026-01-01 13:36:34', '2026-01-01 13:36:34'),
(204, 'Fumbled', 'Fumbled means handled something clumsily, failed to do something smoothly, or made an awkward mistake', 'Physical clumsiness\r\n\r\nDropping or mishandling something\r\n\r\nHe fumbled the keys and dropped them.\r\n\r\nAwkward or nervous action\r\n\r\nActing uncertainly or hesitantly\r\n\r\nShe fumbled with her words during the speech.\r\n\r\nMistake or failure (sports/common use)\r\n\r\nLosing control at an important moment\r\n\r\nThe player fumbled the ball near the goal line.', 'Messed up\r\n\r\nHandled badly\r\n\r\nActed awkwardly', '2026-01-01 14:11:58', '2026-01-01 14:11:58'),
(205, 'We are grooving', 'We are enjoying ourselves, especially with music or rhythm\r\n\r\nWe are in sync and things are going well\r\n\r\nWe are vibing or feeling good together', 'The music’s great—we’re grooving!\r\n\r\nThe team finally understands the plan; we’re grooving now.\r\n\r\nOnce the project started flowing, we were really grooving.', '', '2026-01-01 15:56:28', '2026-01-01 15:56:28'),
(206, 'sneak out', 'Sneak out means to leave a place quietly and secretly, so others don’t notice.\r\nLeave secretly\r\n\r\nSlip away unnoticed', 'Present: sneak out\r\n\r\nPast (US common): snuck out\r\n\r\nPast (UK/formal): sneaked out', 'He snuck/sneaked out of the house at midnight.\r\n\r\nThey tried to sneak out during the boring lecture.', '2026-01-01 16:02:05', '2026-01-01 16:02:05'),
(207, 'But you suck', 'You’re bad at this', '.', '', '2026-01-01 16:13:13', '2026-01-01 16:13:13'),
(208, 'feeble', 'Feeble means weak, lacking strength, power, or effectiveness.', '.', '', '2026-01-01 17:07:16', '2026-01-01 17:07:16'),
(209, 'anthropomorphized', 'When you pretend that something which is NOT human is human — by giving it human feelings, thoughts, or actions.', 'Non-human + human behavior = anthropomorphized', '', '2026-01-01 17:12:19', '2026-01-01 17:12:19'),
(210, 'Nautical', 'Nautical means related to the sea, ships, or sailing.', 'Simple meaning\r\n\r\nConnected with the ocean or seafaring', 'Examples\r\n\r\nHe loves nautical adventures and sea stories.\r\n\r\nThe room has a nautical theme with anchors and ropes.\r\n\r\nShe learned nautical navigation.', '2026-01-01 18:06:40', '2026-01-01 18:06:40'),
(211, 'At the very least', 'कम से कम पर', '.', '', '2026-01-01 18:17:41', '2026-01-01 18:17:41'),
(212, 'Euphemisms', 'euphemisms are polite or indirect words or phrases used instead of harsh, rude, or uncomfortable ones', 'The doctor used euphemisms to soften the bad news.', 'Examples\r\n\r\n“Passed away” → instead of died\r\n\r\n“Let go” → instead of fired\r\n\r\n“Between jobs” → instead of unemployed\r\n\r\n“Senior citizen” → instead of old person\r\n\r\nWhy we use euphemisms\r\n\r\nTo be polite\r\n\r\nTo avoid offending\r\n\r\nTo talk about sensitive topics (death, money, body, mistakes)', '2026-01-01 18:27:40', '2026-01-01 18:27:40'),
(213, 'Grinch', 'Grinch refers to a person who spoils others’ enjoyment, especially by being mean, joyless, or against celebrations.', 'Tone\r\n\r\nInformal\r\n\r\nUsually playful, sometimes mildly insulting', 'Meaning (modern use)\r\n\r\nSomeone who kills the fun\r\n\r\nA joy-spoiler\r\n\r\nA person who is negative or stingy, especially during happy occasions', '2026-01-01 18:30:46', '2026-01-01 18:30:46'),
(214, 'Screw up', 'Don’t screw up the presentation.', 'To make a mistake\r\n\r\nTo mess something up\r\n\r\nTo fail or ruin something', '', '2026-01-01 18:35:51', '2026-01-01 18:35:51'),
(215, 'Screw down', 'To tighten something firmly (literal or figurative)\r\n\r\nTo apply pressure or control\r\n\r\nSometimes used to mean be strict or reduce freedom', 'Screw down the lid tightly.\r\n\r\nThe boss screwed down on expenses.', '', '2026-01-01 18:36:52', '2026-01-01 18:36:52'),
(216, 'suitor', 'A person who seeks to marry or date someone, especially in a formal or old-fashioned sense.', 'She had many suitors competing for her attention.\r\n\r\nIn old stories, the princess rejected all her suitors.\r\n\r\nHe is a wealthy suitor seeking her hand in marriage.', '', '2026-01-01 18:56:38', '2026-01-01 18:56:38'),
(217, 'I don&#039;t get it either', 'मुझे भी समझ नहीं आ रहा है', '.', '', '2026-01-01 18:57:39', '2026-01-01 18:57:39'),
(218, 'She doesn&#039;t strike me as your sort of girl', 'मुझे नहीं लगता कि वो तुम्हारे टाइप की लड़की है।', '.', '', '2026-01-02 15:48:48', '2026-01-02 15:48:48'),
(219, 'Heretical', 'Heretical means going against accepted beliefs, especially religious beliefs, but it can also be used more broadly.', 'Meaning\r\n\r\nHeretical (adjective): holding or expressing beliefs that contradict established doctrine, tradition, or authority.', '“The priest was punished for his heretical views.”\r\n(His beliefs went against the church’s teachings.', '2026-01-02 16:05:02', '2026-01-02 16:05:02'),
(220, 'Bide', 'Bide is a verb that means to wait—especially to wait patiently or quietly for the right time.', 'Bide (verb): to remain, endure, or wait until something happens.', '“Bide one’s time” → wait calmly for a good opportunity\r\n\r\n“She is biding her time before changing jobs.”', '2026-01-02 16:26:21', '2026-01-02 16:26:21'),
(221, 'Invaders', 'Invaders are people or forces that enter a place by force or without permission, usually to take control or cause harm.', 'Invaders (noun): those who invade—enter another land, space, or group aggressively.', '', '2026-01-02 16:30:56', '2026-01-02 16:30:56'),
(222, 'Reassert', 'Reassert means to state or show something again strongly, especially to regain control, authority, or confidence.', 'Authority / control\r\n\r\n“The government moved quickly to reassert control over the region.”\r\n\r\nOpinion / belief\r\n\r\n“She reasserted her position during the meeting.”\r\n\r\nConfidence / identity\r\n\r\n“He tried to reassert himself after the setback.”', '', '2026-01-02 16:32:20', '2026-01-02 16:32:20'),
(223, 'filth', 'गंदगी', '.', '', '2026-01-02 17:43:25', '2026-01-02 17:43:25'),
(224, 'don&#039;t be a coy', 'शर्माओ मत', 'Coy is an adjective that describes someone who is deliberately shy, modest, or evasive, often in a playful or teasing way.', '“She acted coy when asked about the surprise.”\r\n\r\n“Don’t be coy—just tell me the truth.”', '2026-01-02 17:57:38', '2026-01-02 17:57:38'),
(225, 'Chauffeured / Chauffeured', 'Chauffeured (adjective): transported in a vehicle with a professional driver.\r\n\r\n“She arrived in a chauffeured car.”\r\n\r\nChauffeured (verb – past tense): was driven by a chauffeur.\r\n\r\n“He was chauffeured to the airport.”', 'Implies comfort, luxury, or formality\r\n\r\nCommon in contexts like business, VIPs, weddings\r\n\r\nSpelling\r\n\r\nChauffeured → standard spelling\r\n\r\nChauffeurred → less common / often considered a misspelling (extra r)', '', '2026-01-02 18:51:42', '2026-01-02 18:51:42'),
(226, 'Nothing with quirks', '“Nothing with quirks” means nothing unusual, strange, or distinctive—something plain, normal, or conventional.', 'Quirks → odd habits, peculiar features, or small unusual traits', 'Overall meaning\r\n\r\nNo special traits\r\n\r\nNo odd behavior\r\n\r\nNothing out of the ordinary', '2026-01-02 18:55:58', '2026-01-02 18:55:58'),
(227, 'Traits', 'Traits are characteristics or qualities that describe a person, animal, or thing.', 'Meaning\r\n\r\nTraits (noun): distinguishing features, habits, or qualities.', '', '2026-01-02 18:57:50', '2026-01-02 18:57:50'),
(228, 'whipped', 'Whipped means beaten, exhausted, or strongly controlled, depending on how it’s used.', 'Beaten / defeated\r\nThe team was whipped.\r\n→ The team lost badly.', 'Very tired\r\nI’m whipped after work.\r\n→ I am extremely tired.\r\n\r\nControlled by someone (slang)\r\nHe’s whipped by his girlfriend.\r\n→ He does whatever she wants.\r\n\r\nMixed or beaten (cooking)\r\nWhipped cream\r\n→ Cream beaten until light and fluffy.', '2026-01-03 15:27:32', '2026-01-03 15:27:32'),
(229, 'yield', 'Yield means to give way, produce, or surrender, depending on the context.', 'To give way / allow\r\nDrivers must yield to pedestrians.\r\n→ Let others go first.', 'o produce (result or output)\r\nThis land yields good crops.\r\n→ It produces crops.\r\n\r\nTo surrender / give up\r\nThe army refused to yield.\r\n→ They refused to surrender.\r\n\r\nFinance / profit\r\nThe investment yields 10%.\r\n→ It gives a 10% return.', '2026-01-03 15:29:44', '2026-01-03 15:29:44'),
(230, 'Lurking', 'Lurking means staying hidden while watching or waiting, often with a suspicious or secretive purpose.', 'Hiding and watching\r\nSomeone was lurking in the shadows.\r\n→ Hiding and secretly watching.\r\n\r\nQuietly present but not active (online)\r\nHe’s lurking in the chat.\r\n→ Reading messages but not participating.\r\n\r\nUnpleasant feeling or danger that exists quietly\r\nFear was lurking in her mind.\r\n→ Fear was quietly present.', '', '2026-01-03 15:32:55', '2026-01-03 15:32:55'),
(231, 'why did the usurper pardon you?', 'उस हड़पने वाले ने तुम्हें क्षमा क्यों कर दिया?', ',', '', '2026-01-03 15:48:51', '2026-01-03 15:48:51'),
(232, 'You have until dusk to collect your things', 'आपके पास शाम तक अपना सामान इकट्ठा करने का समय है।', 'Dusk is the time just after sunset, when the daylight fades and it starts getting dark.', '', '2026-01-03 15:54:24', '2026-01-03 15:54:24'),
(233, 'What is the punishment for regicide', 'राजहत्या की सजा क्या है?', 'Regicide means the act of killing a king or queen.\r\nregicide = killing a monarch.', '', '2026-01-03 16:07:18', '2026-01-03 16:07:18'),
(234, 'i wasn&#039;t detterd', 'मैं डरा नहीं था।', 'Deterred means discouraged or prevented from doing something because of fear, difficulty, or consequences.', '', '2026-01-03 16:11:00', '2026-01-03 16:11:00'),
(235, 'Wherewithal', 'Wherewithal means having the money, resources, ability, or strength needed to do something.', 'He doesn’t have the wherewithal to start a business.\r\n→ He doesn’t have enough money/skills/resources.\r\n\r\nShe lacked the emotional wherewithal to argue.\r\n→ She didn’t have the emotional strength.', '', '2026-01-03 16:12:25', '2026-01-03 16:12:25'),
(236, 'Relentless', 'Relentless means never stopping, never giving up, and showing no mercy or pause.', 'Simple explanation:\r\n\r\nConstant\r\n\r\nUnyielding\r\n\r\nKeeps going without rest', 'The heat was relentless.\r\n→ It never eased.\r\n\r\nShe faced relentless criticism.\r\n→ The criticism did not stop.\r\n\r\nHe was relentless in pursuing success.\r\n→ He kept going no matter what.', '2026-01-03 16:14:12', '2026-01-03 16:14:12'),
(237, 'I begin to spend inordinate amounts of time watching him', 'मैं उसे देखने में अत्यधिक समय बिताने लगता हूँ।', 'Inordinate means excessive or unusually large, more than what is reasonable or normal.', 'Simple explanation:\r\n\r\nToo much\r\n\r\nBeyond normal limits', '2026-01-03 16:17:05', '2026-01-03 16:17:05'),
(238, 'Beetles', 'Beetles are small insects with hard outer wings (shells).', 'Simple explanation:\r\n\r\nInsects\r\n\r\nHard body covering\r\n\r\nSix legs, two antennae', '', '2026-01-03 16:19:03', '2026-01-03 16:19:03'),
(239, 'Devastated', 'Devastated means extremely upset, shocked, or emotionally destroyed, or completely ruined.', 'Simple meanings:\r\n\r\nEmotionally crushed\r\n\r\nShe was devastated by the loss.\r\n→ She felt deep sadness and shock.\r\n\r\nTotally destroyed (physical/figurative)\r\n\r\nThe village was devastated by the flood.\r\n→ The village was badly damaged.', 'Strength of word: very strong (stronger than sad).', '2026-01-03 17:21:41', '2026-01-03 17:23:36'),
(240, 'Interpret', 'Interpret means to explain the meaning of something or to understand it in a particular way.', '.', 'Simple meanings:\r\n\r\nExplain meaning\r\n\r\nThe teacher interpreted the poem.\r\n→ Explained what it means.\r\n\r\nUnderstand in your own way\r\n\r\nI interpreted his silence as anger.\r\n→ I understood it to mean anger.\r\n\r\nTranslate or perform\r\n\r\nShe interpreted the speech into English.\r\n→ Translated it.\r\n\r\nThe actor interpreted the role brilliantly.\r\n→ Performed the role with their own understanding.', '2026-01-03 17:37:08', '2026-01-03 17:37:08'),
(241, 'her fangs were sharp', 'उसके दांत नुकीले थे', '.', '', '2026-01-03 17:45:26', '2026-01-03 17:45:26'),
(242, 'i reckon', 'मेरा मानना ​​है', 'Reckon means to think, believe, calculate, or judge (often used in informal or British English).', 'Simple meanings:\r\n\r\nThink / believe\r\n\r\nI reckon he’s right.\r\n→ I think he’s right.\r\n\r\nCalculate / estimate\r\n\r\nI reckon it will take two hours.\r\n→ I estimate two hours.\r\n\r\nConsider / judge\r\n\r\nWhat do you reckon about this plan?\r\n→ What do you think?\r\n\r\nCount / settle (older use)\r\n\r\nHe must reckon with the consequences.\r\n→ He must face them.', '2026-01-03 17:48:19', '2026-01-03 17:48:19'),
(243, 'Paranoid', 'Paranoid means having irrational fear or suspicion, often believing that others want to harm, watch, or deceive you', 'In everyday speech, it means overly suspicious.\r\n\r\nIn medical terms, it can describe a mental health condition, but casual use is common.', 'Simple meanings:\r\n\r\nSuspicious without real reason\r\n\r\nHe’s paranoid that people are spying on him.\r\n→ Fear without solid evidence.\r\n\r\nOverly worried (informal use)\r\n\r\nDon’t be paranoid—everything is fine.\r\n→ You’re worrying too much.', '2026-01-04 07:41:08', '2026-01-04 07:41:08'),
(244, 'Stomped', 'Stomped means to step or walk heavily and noisily, often showing anger, force, or excitement.', 'Walk heavily\r\n\r\nHe stomped up the stairs.\r\n→ He walked loudly and forcefully.', 'Walk heavily\r\n\r\nHe stomped up the stairs.\r\n→ He walked loudly and forcefully.', '2026-01-04 07:47:57', '2026-01-04 07:47:57'),
(245, 'ammunition', 'Ammunition means the supply of bullets, shells, or explosives used in weapon', 'The soldiers ran out of ammunition.\r\n→ They had no bullets or shells left.', '', '2026-01-04 07:48:59', '2026-01-04 07:48:59'),
(246, 'Anecdotes', 'Anecdotes are short, interesting stories about real events or people, often personal or amusing.', 'Brief stories\r\n\r\nBased on real life\r\n\r\nUsed to explain, entertain, or support a point', '', '2026-01-04 07:56:41', '2026-01-04 07:56:41'),
(247, 'Dented', 'Dented means having a small hollow or damage caused by being hit or pressed, or slightly harmed (figuratively).', '.', 'Physical damage\r\n\r\nThe car door was dented.\r\n→ It has a small inward bump.\r\n\r\nFigurative (confidence/reputation)\r\n\r\nHis confidence was dented by the failure.\r\n→ His confidence was slightly damaged.', '2026-01-04 08:52:19', '2026-01-04 08:52:19'),
(248, 'omnipotent', 'Omnipotent means having unlimited power; able to do anything.', 'Omni = all\r\n\r\nPotent = powerful', 'God is considered omnipotent.\r\n→ All-powerful.\r\n\r\nHe acted as if he were omnipotent.\r\n→ As if he had unlimited power.', '2026-01-04 17:00:00', '2026-01-04 17:00:00'),
(249, 'You just nodded off again', 'तुम फिर से सो गए।', 'Nodded off means to fall asleep briefly, usually unintentionally.', 'Nodded means moved the head up and down, usually to show agreement, understanding, greeting, or acknowledgement.', '2026-01-04 17:02:31', '2026-01-04 17:02:31'),
(250, 'No resentment', 'कोई नाराजगी नहीं', '.', '', '2026-01-04 19:14:47', '2026-01-04 19:14:47'),
(251, 'She is a kook', 'वह एक सनकी है', '.', '', '2026-01-04 19:24:17', '2026-01-04 19:24:17'),
(252, 'I was worried you were gonna be a vague about it', 'मुझे चिंता थी कि आप इस बारे में अस्पष्ट जवाब देंगे।', 'Vague means not clear, not detailed, or hard to understand', '', '2026-01-05 15:42:16', '2026-01-05 15:42:16'),
(253, 'Smirky', 'Smirky means having a smirk — a self-satisfied, mocking, or sly smile.', '.', '', '2026-01-05 18:21:39', '2026-01-05 18:21:39'),
(254, 'just a smidge', 'बस थोड़ा सा', 'Smidge means a very small amount.\r\nA little\r\n\r\nA tiny bit', 'Add a smidge of salt.\r\n→ Add a very small amount.\r\n\r\nHe was a smidge late.\r\n→ He was a little late.', '2026-01-05 18:44:24', '2026-01-05 18:44:24'),
(255, 'this was a pact', 'यह एक समझौता था', 'Pact means a formal agreement or promise between two or more people or groups.', 'Agreement\r\n\r\nPromise\r\n\r\nOften serious or official', '2026-01-05 18:46:34', '2026-01-05 18:46:34'),
(256, 'snap', 'Snap means something happens suddenly.', 'Snap = sudden break, sound, or anger', 'Break suddenly\r\n\r\nThe stick snapped.\r\n→ It broke suddenly.\r\n\r\nGet angry suddenly\r\n\r\nHe snapped at me.\r\n→ He got angry and shouted.\r\n\r\nQuick sound\r\n\r\nSnap!\r\n→ A sharp sound like breaking fingers.\r\n\r\nQuick photo\r\n\r\nSnap a photo.\r\n→ Take a photo quickl', '2026-01-05 18:50:08', '2026-01-05 18:50:08'),
(257, 'Snapshot', 'Snapshot means a quick picture or a brief look at something at one moment in time.\r\n👉 Snapshot = quick picture or short view', 'Photo 📸\r\n\r\nI took a snapshot of the sunset.\r\n→ A quick photo.', 'Brief overview (figurative)\r\n\r\nThis report gives a snapshot of the economy.\r\n→ A short, quick view of the situation.', '2026-01-05 18:51:48', '2026-01-05 18:51:48'),
(258, 'Plunch US into depression', 'हमें अवसाद में धकेल दिया', 'Plunge means to move, fall, or jump suddenly and forcefully, usually downward or into something.', '', '2026-01-05 19:14:57', '2026-01-05 19:14:57'),
(259, 'What was I hoppy', 'मैं किस बात पर उछल रहा था?', 'Related to hops (beer) 🍺\r\n\r\nThis beer is very hoppy.\r\n→ It has a strong hops flavor (bitter, aromatic).\r\n\r\n2. Jumping / hopping (less common)\r\n\r\nA hoppy little puppy.\r\n→ A puppy that hops around a lot.', '', '2026-01-05 19:16:59', '2026-01-05 19:16:59'),
(260, 'Plunk', 'Plunk = to put or drop something suddenly and heavily\r\nhink of the sound “plunk!” 💥 — something falls and makes a dull noise.', 'Simple examples\r\n\r\nHe plunked the glass on the table.\r\n👉 He put it down hard, not gently.\r\n\r\nShe plunked herself on the chair.\r\n👉 She sat down heavily.\r\n\r\nThe stone fell into water — plunk!\r\n👉 The sound it made.', '👉 Plunk = drop / put with a heavy sound', '2026-01-06 15:36:49', '2026-01-06 15:36:49'),
(261, 'How come this lady lives with another lady', 'यह महिला दूसरी महिला के साथ क्यों रहती है?', 'How come = why', '', '2026-01-06 15:42:29', '2026-01-06 15:42:29'),
(262, 'Fling', 'Fling = to throw something suddenly and with force', 'It suggests quick, careless, or angry movement.', '1️⃣ Throw forcefully\r\n\r\nHe flung the ball across the field.\r\n\r\nShe flung the door open.\r\n\r\n2️⃣ Move suddenly\r\n\r\nHe flung himself onto the bed.\r\n👉 He dropped himself quickly.\r\n\r\n3️⃣ Short romantic relationship (noun)\r\n\r\nThey had a summer fling.\r\n👉 A brief, casual romance.', '2026-01-06 15:45:23', '2026-01-06 15:45:23'),
(263, 'Nauseous', 'Nauseous = feeling sick, like you want to vomit 🤢\r\n👉 Nauseous = sick to your stomach', 'Common confusion (important)\r\n\r\nNauseous → feeling sick\r\n\r\nNauseating → causing sickness\r\n\r\n✔ I feel nauseous\r\n✔ That smell is nauseating', 'I feel nauseous after the ride.\r\n\r\nThe smell made her nauseous.\r\n\r\nHe became nauseous from the pain.', '2026-01-06 15:48:42', '2026-01-06 15:48:42'),
(264, 'I am out of sorts', 'मेरी तबीयत ठीक नहीं है।', 'Out of sorts = not feeling well (physically or mentally)', '', '2026-01-06 15:58:43', '2026-01-06 15:58:43'),
(265, 'shot', '👉 Short = length / size\r\n👉 Shot = hit / try / photo / past of shoot', 'Meaning:\r\n1️⃣ an act of firing or hitting\r\n2️⃣ a try or attempt\r\n3️⃣ a photograph / film scene\r\n4️⃣ a small drink (informal)', '', '2026-01-06 16:03:02', '2026-01-06 16:03:02'),
(266, 'He made a move on me', 'उसने मेरे साथ गलत हरकत करने की कोशिश की', '👉 He showed romantic or sexual interest in me', 'What kind of “move”?\r\n\r\nIt could be:\r\n\r\nflirting\r\n\r\ntrying to kiss\r\n\r\ntouching in a romantic way\r\n\r\nasking for something intimate', '2026-01-06 16:05:39', '2026-01-06 16:05:39'),
(267, 'He made a pass on me', 'He made a pass at me\r\nHe tried to flirt with me or showed sexual/romantic interest', 'A pass = an advance (not a sports pass).\r\n\r\nIt can include:\r\n\r\nflirting\r\n\r\nsuggestive comments\r\n\r\ntrying to touch\r\n\r\nasking for something romantic/sexual', '.', '2026-01-06 16:12:11', '2026-01-06 16:12:11'),
(268, 'Unleashed', 'Unleashed = set free / released / allowed to act without control', '👉 Unleashed = let loose / no longer controlled', 'मैंने उसे तुम्हारे ऊपर छोड़ दिया', '2026-01-06 16:16:39', '2026-01-06 16:16:39'),
(269, 'It&amp;#039;s time to swoop in', 'अब हमला करने का समय आ गया है', 'It’s time to act quickly and decisively, often by stepping in at the perfect moment.', 'swoop = झपट्टा', '2026-01-06 16:21:12', '2026-01-06 16:23:03'),
(270, 'Distraught', 'Distraught = extremely upset and emotionally shaken\r\n\r\nIt means someone is so worried, sad, or shocked that they can’t think clearly.', 'Upset → mild\r\n\r\nDistressed → strong\r\n\r\nDistraught → very strong', '👉 Distraught = deeply upset and unable to stay calm', '2026-01-06 16:24:50', '2026-01-06 16:24:50'),
(271, 'Shutout  Shutdown', 'Shutout  : Meaning: to completely prevent someone from participating or scoring\r\nUse: sports, competitions, access/exclusion', 'Shutdown\r\nMeaning: to stop or close operations\r\nUse: businesses, systems, machines, services\r\n👉 Focus = stopping activity', '', '2026-01-06 16:33:18', '2026-01-06 16:33:18'),
(272, 'bail on someone', 'Bail on someone = leave them, cancel plans, or not show up when you promised.', 'Tone &amp; feeling\r\n\r\nDon’t you dare → strong threat / warning\r\n\r\nOften said when the speaker would feel hurt or betrayed\r\nDon&#039;t you dare bail on me', 'Don’t you dare bail on me tonight.\r\n\r\nHe bailed on me at the last minute.\r\n\r\nPlease don’t bail on me — I need you.', '2026-01-06 18:51:18', '2026-01-06 18:51:18'),
(273, 'So do we have the best friends or what', 'तो क्या हमारे सबसे अच्छे दोस्त हैं या नहीं?', ',', '', '2026-01-06 19:03:53', '2026-01-06 19:03:53'),
(274, 'He wants to do something electic', 'वह कुछ अनूठा करना चाहता है।', '.', '', '2026-01-08 15:40:08', '2026-01-08 15:40:08'),
(275, 'You know I don&#039;t mean to brag', 'आप जानते हैं कि मेरा इरादा शेखी बघारने का नहीं है।', '.', '', '2026-01-08 15:54:30', '2026-01-08 15:54:30'),
(276, 'In the cab on the way over he blazed up A doobie', 'रास्ते में टैक्सी में उसने एक डूबी (गांजा) जलाया।', 'Blazed = burned or shone intensely; showed strong force or emotion', '', '2026-01-08 18:52:24', '2026-01-08 18:52:24'),
(277, 'Smack', 'Smack = a sharp hit, sound, or strong taste/suggestion', '.', '', '2026-01-08 18:55:10', '2026-01-08 18:55:10'),
(278, 'You scared the crap out of me', 'तुमने मुझे बुरी तरह डरा दिया', '.', '', '2026-01-09 18:59:31', '2026-01-09 18:59:31'),
(279, 'He is really nusty about you', 'वो तुम्हारे लिए बहुत दीवाना है', '.', '', '2026-01-09 19:12:04', '2026-01-09 19:12:04'),
(280, 'vicious', 'Vicious means cruel, violent, or deliberately harmful—either in actions, words, or character', 'Simple synonyms\r\n\r\nCruel, brutal, savage, nasty, malicious', 'Cruel or violent behavior\r\n\r\nA vicious attack → very brutal and savage\r\n\r\nMalicious or spiteful speech\r\n\r\nVicious rumors → intended to hurt someone\r\n\r\nSevere or intense (non-physical)\r\n\r\nA vicious cycle → a harmful situation that keeps repeating and getting worse\r\n\r\nDangerous temperament (animals/people)\r\n\r\nA vicious dog → likely to attack', '2026-01-10 19:07:54', '2026-01-10 19:07:54'),
(281, 'astounding', 'Astounding means extremely surprising or impressive—something that makes you feel shock or amazement because it’s so unexpected or remarkable.', '.', 'Difference between astounding and astonishing\r\n\r\nAstounding → very strong surprise, often positive\r\n\r\nAstonishing → similar, but slightly more formal', '2026-01-10 19:11:43', '2026-01-10 19:11:43'),
(282, 'He is very docile', 'वह बहुत ही आज्ञाकारी है।', 'Docile means calm, obedient, and easy to control, especially when talking about animals or people who don’t resist or argue.', 'Common uses\r\n\r\nAnimals: A docile horse / dog\r\n\r\nPeople: A docile student (one who follows rules quietly)', '2026-01-10 19:25:58', '2026-01-10 19:25:58'),
(283, 'saucy', 'talking or behaving in a bold, cheeky, or slightly disrespectful way, often playfully.', 'Don’t be saucy with your elders.\r\n(Don’t talk back rudely or cheekily.', '', '2026-01-11 13:51:49', '2026-01-11 13:51:49'),
(284, 'Oh my life is so amuzing', 'ओह, मेरी जिंदगी कितनी मजेदार है!', 'Amusing (adjective) means funny or entertaining; something that makes you smile or laugh', '', '2026-01-11 13:54:58', '2026-01-11 13:54:58'),
(285, 'It&#039;s icky', 'यह घिनौना है', 'Icky (adjective) means unpleasant, disgusting, or something that makes you feel uncomfortable', '', '2026-01-11 14:01:38', '2026-01-11 14:01:38'),
(286, 'gouged', 'Cut or dig out forcefully\r\n\r\nThe knife gouged a deep hole in the wood.\r\n👉 Made a deep cut.', 'Injure by digging or tearing\r\n\r\nHe gouged his knee on the rock.\r\n👉 Hurt badly by scraping.', 'The shopkeeper gouged customers during the shortage.\r\n👉 Charged unfairly high prices.\r\n👉 Gouged = deeply cut or unfairly overcharged', '2026-01-11 14:21:25', '2026-01-11 14:21:25'),
(287, 'resent', 'क्रोध करना', 'Resent = to feel angry or bitter about something you think is unfair\r\n.', '', '2026-01-11 15:26:49', '2026-01-11 15:26:49'),
(288, 'fortune', 'Fortune can mean luck or a large amount of money, depending on', 'Luck (good or bad)\r\n\r\nGood fortune smiled on him.\r\n👉 Good luck.\r\n\r\nBy fortune, no one was hurt.\r\n👉 By chance.', 'She made a fortune in business.\r\n👉 A lot of money.', '2026-01-11 16:22:12', '2026-01-11 16:22:12'),
(289, 'I know neither did I', '👉 Both of us didn’t know / didn’t do it\r\n\r\nIt’s used when you agree with someone about a negative statement.', 'Example conversation\r\n\r\nA: I didn’t know about the meeting.\r\nB: I know. Neither did I.\r\n👉 Both people were unaware.', '', '2026-01-11 16:35:00', '2026-01-11 16:35:00'),
(290, 'Vulnerable', 'Vulnerable = easily hurt, harmed, or affected\r\n\r\nThis can be physical, emotional, or situational.', 'Vulnerable = not protected; easy to hurt', 'Common uses\r\n1️⃣ Physically unsafe\r\n\r\nThe child is vulnerable to disease.\r\n👉 Easily affected.\r\n\r\n2️⃣ Emotionally open\r\n\r\nShe felt vulnerable sharing her feelings.\r\n👉 Easily hurt emotionally.\r\n\r\n3️⃣ Weak / unprotected situation\r\n\r\nThe system is vulnerable to attacks.\r\n👉 Not well protected.', '2026-01-11 17:44:14', '2026-01-11 17:44:14'),
(291, 'Amused', 'Amused = feeling entertained or mildly happy\r\n\r\nIt’s a gentle, quiet kind of laughter or enjoyment, not loud laughter.', 'She looked amused by his joke.\r\n\r\nHe was amused to see the cat chasing its tail.\r\n\r\nI’m amused, not impressed', '', '2026-01-11 17:54:57', '2026-01-11 17:54:57'),
(292, 'Freak out', 'Freak out = suddenly become very scared, angry, or excited and lose control', '👉 Freak out = panic or overreact suddenly', '', '2026-01-11 18:10:06', '2026-01-11 18:10:06'),
(293, 'Intimidated', 'Intimidated = feeling scared, nervous, or less confident because of someone or something', '👉 Intimidated = made to feel afraid or not confident', 'I felt intimidated by his confidence.\r\n\r\nShe was intimidated during the interview.\r\n\r\nThe big crowd intimidated him.', '2026-01-11 18:19:10', '2026-01-11 18:19:10'),
(294, 'paranoid', 'Paranoid = feeling extremely suspicious or afraid without a clear reason', 'Paranoid = unnecessarily suspicious or fearful', 'He’s paranoid about people judging him.\r\n\r\nShe felt paranoid walking alone at night.\r\n\r\nDon’t be paranoid—no one is talking about you.', '2026-01-11 18:20:48', '2026-01-11 18:20:48'),
(295, 'It&#039;s very faint', 'यह बहुत धुंधला है', 'Faint means weak, not clear, or barely noticeable. It can be used in a few different ways:', '', '2026-01-12 15:02:54', '2026-01-12 15:02:54'),
(296, 'Why is that difficult to comprehend', 'यह समझना इतना मुश्किल क्यों है?', 'Comprehend means to understand something fully, especially something complex or difficult.', 'I can read the instructions, but I don’t fully comprehend them.', '2026-01-12 18:27:00', '2026-01-12 18:27:00'),
(297, 'Dinkus', '“Dinkus” is an informal, slang insult. It means:', 'a silly, foolish, or clueless person', '“Don’t be a dinkus—check the code before pushing!”', '2026-01-14 12:13:25', '2026-01-14 12:13:25'),
(298, 'slack', 'leniency, forgiveness, or being less strict\r\nBe more understanding toward him; don’t judge or punish him too harshly.', '.', '', '2026-01-14 12:16:04', '2026-01-14 12:16:04'),
(299, 'I have been feeling so lousy', 'मुझे बहुत खराब लग रहा है', 'Lousy means very bad, poor, or unpleasant.', '', '2026-01-14 18:49:12', '2026-01-14 18:49:12'),
(300, 'sober', 'Sober means not drunk and thinking clearly in a calm, serious way.', 'Serious and calm\r\n\r\nIt describes a person or mood that is serious, thoughtful, and not playful.\r\n\r\nShe gave a sober explanation of the situation.', '', '2026-01-14 19:07:59', '2026-01-14 19:07:59'),
(301, 'This situation is much more dire than we expected', 'यह स्थिति हमारी अपेक्षा से कहीं अधिक गंभीर है।', '.', '', '2026-01-14 19:21:48', '2026-01-14 19:21:48'),
(302, 'It seems so futile', 'यह बहुत ही व्यर्थ लगता है', 'Futile means useless or pointless—something that has no chance of success or produces no result.', '', '2026-01-15 16:01:53', '2026-01-15 16:01:53'),
(303, 'Stick a fork', 'idiom that means something is finished, done, or cannot be improved anymore.', ',', '', '2026-01-15 17:17:10', '2026-01-15 17:17:10'),
(304, 'you are swell', 'You are swell” means you are great, kind, or very nice 😊\r\n\r\nIt’s a compliment, a bit old-fashioned, but still friendly.', '.', '', '2026-01-15 17:19:58', '2026-01-23 18:41:30'),
(305, 'Reckoned with', '“Reckoned with” means to be considered seriously or treated as a powerful factor that cannot be ignored.', '.', '', '2026-01-15 18:25:10', '2026-01-15 18:25:10'),
(306, 'Discreet &amp; Discrete', 'Discreet means careful, private, and not drawing attention—especially with sensitive information or behavior', 'Discrete ✅ → means separate or distinct', '', '2026-01-15 18:34:56', '2026-01-15 18:34:56'),
(307, 'spread misery', 'spread misery =&gt; cause suffering, pain, or unhappiness', 'throughout the land =&gt; everywhere in the country', '', '2026-01-15 18:40:55', '2026-01-15 18:40:55'),
(308, 'Concessions', 'Concession = compromise / allowance / relaxation of rules', 'Concessions means things that are given up, allowed, or agreed to—usually to reach a compromise or agreement.', '', '2026-01-15 18:44:31', '2026-01-15 18:44:31'),
(309, 'Wary of strangers', 'Wary → careful, cautious, not fully trusting\r\n\r\nStrangers → people you do not know', '.', '', '2026-01-16 13:07:13', '2026-01-16 13:07:13'),
(310, 'Conspicuous', 'Very noticeable\r\n\r\nEasy to see\r\n\r\nStanding out in a crowd', '.', '', '2026-01-16 17:12:53', '2026-01-16 17:12:53'),
(311, 'Ecstatic', 'Ecstatic means extremely happy, joyful, or excited—so happy that it feels overwhelming.', '.', '', '2026-01-17 14:15:55', '2026-01-17 14:15:55'),
(312, 'profound', 'Profound means very deep, serious, or having great meaning or importance', '.', 'You have to profound our faith', '2026-01-17 15:02:33', '2026-01-17 15:03:08'),
(313, 'Corrosive', 'Corrosive means able to slowly destroy, damage, or eat away something—either physically or emotionally.', '1️⃣ Physical / chemical meaning\r\n\r\nSomething that burns or eats away materials (like metal or skin).', '👉 Corrosive = slowly destructive', '2026-01-17 15:12:53', '2026-01-17 15:12:53'),
(314, 'Peeking', 'Peeking means looking quickly or secretly at something, often when you’re not supposed to', '.', '', '2026-01-17 16:13:02', '2026-01-17 16:13:02'),
(315, 'You are so smitten', 'तुम तो पूरी तरह से मोहित हो।', '.', '', '2026-01-17 16:21:19', '2026-01-17 16:21:19'),
(316, 'gross', '→ Means disgusting, unpleasant, offensive\r\n→ Can be physical (messy, dirty) or emotional/moral (creepy, inappropriate)', '.', '', '2026-01-17 18:37:54', '2026-01-17 18:37:54'),
(317, 'Let me live vicariously', 'मुझे दूसरों के अनुभवों से जीने दो', 'Vicariously means experiencing something indirectly through another person, instead of doing it yourself.', '', '2026-01-17 18:50:05', '2026-01-17 18:50:05'),
(318, 'Spontaneously', 'Spontaneously means something happens naturally, suddenly, or without planning.', 'Clear explanation\r\n\r\nWhen something happens spontaneously, it:\r\n\r\nis not planned in advance\r\n\r\nhappens on its own or in the moment', '', '2026-01-17 19:11:12', '2026-01-17 19:11:12'),
(319, 'Doofus', '👉 Meaning: a stupid, foolish, or silly person.\r\nIt’s an insult, but usually a mild or playful one, not very harsh.', '.', '', '2026-01-18 16:14:08', '2026-01-18 16:14:08'),
(320, 'He is kind of intense.', 'It means he’s a bit too strong, serious, emotional, or overwhelming in how he acts—more than what feels normal or comfortable.', 'intense → very serious, focused, emotional, aggressive, or high-energy', '', '2026-01-18 17:21:57', '2026-01-18 17:21:57'),
(321, 'This is nuts.', 'Something is crazy, unbelievable, shocking, or ridiculous.\r\n\r\nIt’s informal and often used to show surprise, frustration, or disbelief.', 'This workload is nuts. (too much)\r\n\r\nThe traffic today is nuts. (crazy)\r\n\r\nThat price is nuts! (unbelievable)\r\n\r\nWhat’s happening here is nuts. (chaotic)', '', '2026-01-18 17:52:06', '2026-01-18 17:52:06'),
(322, 'Chaos', 'state of complete disorder, confusion, or lack of control.', 'The office was in chaos after the system crashed.\r\n\r\nThe city fell into chaos during the blackout.', 'Chaos = the condition 🌀\r\n\r\nChaotic = having that condition\r\nfull of chaos; describing something that is disordered or out of control.\r\n\r\nIt describes a noun.', '2026-01-18 17:54:55', '2026-01-18 17:54:55'),
(323, 'romp', 'playful, energetic activity', '..', '', '2026-01-18 18:00:28', '2026-01-18 18:00:28'),
(324, 'Fugitive', 'A fugitive is a person who is running away or hiding to avoid being caught, arrested, or punished.', '.', '', '2026-01-19 10:48:39', '2026-01-19 10:48:39'),
(325, 'Vandalism', 'Vandalism means deliberately damaging, defacing, or destroying someone else’s property.', 'Vandalism = intentional property damage', '', '2026-01-19 16:52:39', '2026-01-19 16:52:39'),
(326, 'evict', 'Evict means to force someone to leave a property, usually a home or land, by legal authority.', 'Evict = make someone leave a place they are living in (legally)', '', '2026-01-19 17:56:11', '2026-01-19 17:56:11'),
(327, 'Sneak off', 'Sneak off means to leave a place quietly and secretly, usually so other people don’t notice.', '.', '', '2026-01-21 18:02:41', '2026-01-21 18:02:41'),
(328, 'Resilience', 'Resilience means the ability to recover quickly from difficulties and keep going.', 'Resilience = bouncing back after stress, failure, or hardship', '', '2026-01-28 10:08:16', '2026-01-28 10:08:16'),
(329, 'Have you ever sowed me the field', 'क्या आपने कभी खेत में बीज बोए हैं?', '.“Sowed” is the past tense of “sow.”\r\nTo scatter or plant seeds in the ground', '', '2026-02-01 05:21:39', '2026-02-01 05:23:29'),
(330, 'Sheer', 'very great, vast, extreme', '.', '', '2026-02-01 05:58:24', '2026-02-01 05:58:24'),
(331, 'Catered to', 'Catered to → provided for, served, satisfied', '.', '', '2026-02-01 05:58:55', '2026-02-01 05:58:55'),
(332, 'Fornication', 'Fornication means consensual sexual intercourse between people who are not married to each other.', '.', '', '2026-02-01 16:42:39', '2026-02-01 16:42:39'),
(333, 'Adhere', 'Adhere means to stick to something — either physically or by following rules, beliefs, or instructions.', 'Adhere का मतलब होता है किसी चीज़ से मजबूती से जुड़े रहना या किसी नियम/सिद्धांत का पालन करना।', '', '2026-02-01 16:46:46', '2026-02-01 16:46:46'),
(334, 'Presides', 'Presides means to be in charge of a meeting, event, or official process, especially in a formal or authoritative role.', 'Leads or oversees something\r\n\r\nActs as the chair or head', '', '2026-02-01 16:51:47', '2026-02-01 16:51:47'),
(335, 'delegate', '.', 'a person who has been chosen to speak or take decisions for a group of people, especially at a meeting', '', '2026-02-02 11:15:06', '2026-02-02 11:15:06'),
(336, 'My own sister married someone she loathed as well', 'मेरी बहन ने भी ऐसे व्यक्ति से शादी की जिससे वह नफरत करती थी।', '.', '', '2026-02-02 16:21:18', '2026-02-02 16:21:18'),
(337, 'stubborn', 'जिद्दी', '.', '', '2026-02-02 16:48:09', '2026-02-02 16:48:09'),
(338, 'Wrecked', 'Destroyed or badly damaged', '..', '', '2026-02-06 12:08:25', '2026-02-06 12:08:25'),
(339, 'Inflict', 'Inflict = to cause something unpleasant or painful to someone.', '.', '', '2026-02-06 13:07:45', '2026-02-06 13:07:45'),
(340, 'Laceration', 'Laceration = a deep cut or tear in the skin or flesh.', 'The doctor stitched the laceration on his arm.\r\n(He had a deep cut on his arm.)', '', '2026-02-06 13:09:13', '2026-02-06 13:09:13'),
(341, 'Evisceration', 'Removal of internal organs, especially from the abdomen.', 'The surgeon performed an evisceration during the operation.', '', '2026-02-06 13:10:23', '2026-02-06 13:10:23'),
(342, 'abdomen', 'Abdomen = the part of the body between the chest and the hips.\r\nIt contains organs like the stomach, liver, and intestines.', '.', '', '2026-02-06 13:10:55', '2026-02-06 13:10:55'),
(343, 'Incineration', 'Incineration = the process of burning something completely until it turns into ashes.\r\n\r\nThe hospital uses incineration to dispose of medical waste.\r\n\r\nThe documents were destroyed by incineration.', '.', '', '2026-02-06 13:12:04', '2026-02-06 13:12:04'),
(344, 'Moaning', 'Making a low sound because of pain or discomfort', 'He was moaning in pain after the injury.', '', '2026-02-06 13:21:03', '2026-02-06 13:21:03'),
(345, 'Blazed', 'Burned very brightly or strongly', 'The fire blazed all night.\r\n(It burned with strong flames.)', '', '2026-02-06 13:24:35', '2026-02-06 13:24:35'),
(346, 'Crevice', 'Crevice means a narrow crack or small opening, especially in a rock, wall, or ground.', 'दरार / संकीर्ण दरार', '', '2026-02-07 14:21:09', '2026-02-07 14:21:09'),
(347, 'Devours', 'Devours means eats something quickly and eagerly, often completely.', '.', '', '2026-02-07 14:34:15', '2026-02-07 14:34:15'),
(348, 'Inference', 'Inference means a conclusion or idea that you understand from evidence and reasoning, not from direct statements.', 'If the ground is wet, you make an inference that it rained.\r\n\r\nFrom his smile, I made the inference that he was happy', '', '2026-02-19 09:06:40', '2026-02-19 09:06:40'),
(349, 'Vengeance', 'Vengeance means punishment or revenge taken because someone has hurt you or done something wrong to you.', '...', '', '2026-02-20 15:12:02', '2026-02-20 15:12:02'),
(350, 'Absurd', '“Absurd” means something that is completely unreasonable, illogical, or makes no sense—often so silly that it’s almost funny.', '/', '', '2026-04-05 18:23:38', '2026-04-05 18:23:38'),
(351, 'Bitchin', '. Very cool / awesome (positive meaning, common in American slang)\r\nExample: “That bike is bitchin’!”\r\n👉 Meaning: It’s really cool or impressive.', '..', '', '2026-04-06 19:37:14', '2026-04-06 19:37:14'),
(352, 'tainted', 'What “tainted” means here:\r\nImpure\r\nCorrupted\r\nDamaged (emotionally or morally)', 'The sentence “He is the boy with a tainted heart” means:', '', '2026-04-07 15:55:36', '2026-04-07 15:55:36'),
(353, 'rational', '“rational” = logical, sensible, based on thinking', 'The sentence “And this type of love isn’t rational” means:\r\n👉 This kind of love is not logical or based on reason', '', '2026-04-07 15:58:57', '2026-04-07 15:58:57'),
(354, 'Swelling', 'Swelling means an increase in size of a body part, usually because of injury, infection, or fluid buildup.', '.', '', '2026-04-10 21:26:21', '2026-04-10 21:26:21'),
(355, 'Carnage', '“Carnage” means a lot of death, destruction, or violence, especially after a fight, accident, or disaster.', '.', '', '2026-04-17 19:55:38', '2026-04-17 19:55:38'),
(356, 'Regardless', 'Regardless = without being affected by conditions, obstacles, or other people', '“I will win regardless” means:\r\n\r\n👉 “No matter what happens, I’m going to win.”', '', '2026-04-24 15:14:38', '2026-04-24 15:14:38'),
(357, 'Regardless', 'Regardless = without being affected by conditions, obstacles, or other people', '“I will win regardless” means:\r\n\r\n👉 “No matter what happens, I’m going to win.”', '', '2026-04-24 15:14:38', '2026-04-24 15:14:38'),
(358, 'Instinctively', 'Instinctively means doing something automatically, without thinking, based on natural instinct or gut feeling.', '“She instinctively moved out of the way.”\r\n“He instinctively knew something was wrong.”', '', '2026-04-24 15:23:44', '2026-04-24 15:23:44'),
(359, 'Naive', '“Naive” (also spelled “naïve”) means someone who is too trusting, innocent, or inexperienced, especially in a way that makes them easy to fool.', '“He was naive to believe everything he heard.”\r\n“She’s naive about how the real world works.”', '', '2026-04-24 20:03:49', '2026-04-24 20:03:49'),
(360, 'Shrug', '“Shrug” means to raise your shoulders slightly to show you don’t know, don’t care, or are unsure.', '.', '.', '2026-04-24 20:07:21', '2026-04-24 20:07:21'),
(361, 'Frown', '“Frown” means to make a facial expression where your eyebrows come down and your mouth curves downward, usually showing sadness, चिंता, or disapproval.', '/.', '', '2026-04-24 20:08:15', '2026-04-24 20:08:15'),
(362, 'Don’t rein me in', '“Don’t rein me in” means “Don’t control me” or “Don’t hold me back.”', 'The phrase comes from horse reins, which are used to control a horse’s movement.', '', '2026-04-24 20:09:27', '2026-04-24 20:09:27'),
(363, 'Can you just lay off?', 'means “Can you stop?” or “Leave me alone.”', 'It is usually said when someone is bothering, criticizing, or pressuring you too much.', '', '2026-04-24 20:10:22', '2026-04-24 20:10:22'),
(364, 'Shimmy', '“Shimmy” means to shake or wiggle your body, especially your shoulders or hips.', '/.', '', '2026-04-24 20:11:37', '2026-04-24 20:11:37'),
(365, 'Carnage', '“Carnage” means a lot of death, destruction, or violence, especially after a fight, accident, or disaster.', 'dc', '', '2026-04-24 20:12:09', '2026-04-24 20:12:09'),
(366, 'Spooky', '“Spooky” means scary, creepy, or ghost-like.', '“That old house looks spooky.”\r\n“It was a spooky story.”', '', '2026-04-24 20:12:34', '2026-04-24 20:12:34'),
(367, 'Hurl', '“Hurl” usually means to throw something forcefully.\r\n\r\n“He hurled the ball across the field.”\r\n\r\nIt can also mean to vomit in informal speech.', '.', '', '2026-04-24 20:13:02', '2026-04-24 20:13:02'),
(368, 'Shady', '“Shady” usually means suspicious, dishonest, or untrustworthy.', '.', '', '2026-04-24 20:13:37', '2026-04-24 20:13:37'),
(369, 'shackle', 'A shackle is something used to restrain or chain a person&#039;s hands or feet, like handcuffs or chains on prisoners.', 'It can also be used figuratively to mean something that limits freedom.', '', '2026-04-24 20:15:36', '2026-04-24 20:15:36'),
(370, 'stubborn', 'A stubborn person is determined to do what he or she wants and refuses to do anything else:', 'opposed to change or suggestion:', '', '2026-04-25 19:02:26', '2026-04-25 19:02:26');
